'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DEMO=new URLSearchParams(location.search).get('demo')==='1';
const KEY=DEMO?'haru-integrated-demo-v1':'haru-integrated-v1';
const iso=(d=new Date())=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul'}).format(d);
const today=iso();const addDays=(day,n)=>{const d=new Date(day+'T12:00:00+09:00');d.setUTCDate(d.getUTCDate()+n);return iso(d)};
const monday=day=>{const d=new Date(day+'T12:00:00+09:00');return addDays(day,-((d.getUTCDay()+6)%7))};
const week=monday(today);const quarter=today.slice(0,4)+'-Q'+Math.ceil(Number(today.slice(5,7))/3);
const defaults=()=>({version:1,profile:{vision:'',principle:'',strengths:''},roles:[{id:'invest',name:'투자 회사',kind:'본업',role:'이사',purpose:'',hours:''},{id:'works',name:'워크스워크',kind:'사이드프로젝트',role:'',purpose:'',hours:''},{id:'pwr',name:'PWR',kind:'사이드프로젝트',role:'',purpose:'',hours:''},{id:'family',name:'가족·관계',kind:'삶',role:'',purpose:'',hours:''},{id:'self',name:'나 자신',kind:'삶',role:'',purpose:'',hours:''}],goals:[],tasks:[],notes:[],health:[],people:[],moments:[],issues:[],investments:[],loans:[],incomes:[],decisions:[],reviews:[],timeLogs:[],focus:[]});
const arrays=['roles','goals','tasks','notes','health','people','moments','issues','investments','loans','incomes','decisions','reviews','timeLogs','focus'];
let db=defaults(),storageError=false,fieldCounter=0;
const requiredStrings={roles:['name','kind','role','purpose','hours'],goals:['title','kind','role','why','outcome','target','obstacle','plan'],tasks:['title','goal','role','date'],notes:['text','date','role'],health:['date','sleep','weight','minutes','mood','drink','memo'],people:['name','group','note'],moments:['person','title','date','minutes','note'],issues:['person','title','next','date'],investments:['name','principal','value','date','reason'],loans:['name','balance','asof','rate','monthly','method','date','maturity'],incomes:['title','amount','date','role'],decisions:['title','created','expected','date','actual','strength'],reviews:['kind','period','result','obstacle','next','stop'],timeLogs:['title','role','date','minutes','note'],focus:['period','task']};
function validState(d){return !!d&&d.version===1&&d.profile&&typeof d.profile==='object'&&['vision','principle','strengths'].every(k=>typeof d.profile[k]==='string')&&arrays.every(k=>Array.isArray(d[k])&&d[k].length<=10000&&new Set(d[k].map(r=>r?.id)).size===d[k].length&&d[k].every(r=>r&&typeof r==='object'&&typeof r.id==='string'&&requiredStrings[k].every(f=>typeof r[f]==='string')&&(!['tasks','issues','incomes'].includes(k)||typeof r.done==='boolean')&&Object.values(r).every(v=>typeof v==='string'||typeof v==='boolean')))}
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(!validState(parsed))throw Error('invalid');db=parsed}}catch{storageError=true}
if(DEMO&&!storageError){try{if(!localStorage.getItem(KEY))db=demoState()}catch{storageError=true}}
function commit(edit,message='저장했어요.'){if(!DEMO&&window.HaruSync){const next=structuredClone(db);edit(next);return HaruSync.commit(next);}if(storageError){toast('기존 데이터 읽기에 실패했습니다. 백업을 확인한 뒤 다시 시도해주세요.');return false}const next=structuredClone(db);edit(next);try{localStorage.setItem(KEY,JSON.stringify(next));db=next;render();if(message)toast(message);return true}catch{toast('저장하지 못했어요. 브라우저 저장 공간과 권한을 확인해주세요.');return false}}
const id=()=>crypto.randomUUID();const find=(table,key)=>db[table].find(x=>x.id===key);const byName=(table,key,fallback='연결 없음')=>find(table,key)?.name||find(table,key)?.title||fallback;
const num=v=>Number(v)||0;const money=v=>'₩ '+Math.round(num(v)).toLocaleString('ko-KR');const sum=(rows,key)=>rows.reduce((a,r)=>a+num(r[key]),0);
const finished=g=>{const rows=lifeModel().allTasks.filter(t=>t.goal===g.id);return {total:rows.length,done:rows.filter(t=>t.done).length,next:rows.find(t=>!t.done)}};
const periodDate=()=>new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'long',day:'numeric',weekday:'long'}).format(new Date());
const navigation=[['home','⌂','홈',''],['calendar','▦','캘린더','연결'],['notes','▤','기록','수시'],['goals','✧','목표·꿈','분기·연'],['work','▦','일','주간'],['money','◴','돈','월간'],['health','♡','건강','선택'],['relations','♧','관계','수시'],['review','↺','돌아보기','매일·주간']];
let page=location.hash.slice(1)||'home',filter='전체',reviewKind='일간',reviewPeriod=today;let timer;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',3500)}
const btn=(text,action,data={},style='quiet')=>`<button type="button" class="${style}" data-action="${action}" ${Object.entries(data).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ')}>${esc(text)}</button>`;
const tag=(t,tone='')=>`<span class="tag ${tone}">${esc(t)}</span>`;
const card=(title,body,action='',extra='')=>`<section class="card ${extra}"><div class="cardhead"><h2>${title}</h2>${action}</div>${body}</section>`;
const heading=(label,title,description,action='')=>`<div class="heading"><div><span class="eyebrow">${label}</span><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${action||`<span class="date">${periodDate()}</span>`}</div>`;
const empty=(text,action='')=>`<div class="empty">${text}${action?'<div style="margin-top:12px">'+action+'</div>':''}</div>`;
const row=(left,right='')=>`<div class="row"><div>${left}</div>${right}</div>`;
const roleOptions=()=>db.roles.map(r=>[r.id,r.name]);
const goalOptions=()=>db.goals.map(g=>[g.id,g.title]);
const personOptions=()=>db.people.map(p=>[p.id,p.name]);
const goalRole=g=>byName('roles',g.role,'개인 목표');
function taskRow(t,showRole=false){return `<div class="row"><label class="check"><input type="checkbox" data-toggle="tasks" data-id="${t.id}" ${t.done?'checked':''}><span>${esc(t.title)}${showRole?`<p>${esc(byName('roles',t.role,'개인'))}</p>`:''}</span></label><div class="line-actions">${t.date?`<small class="${!t.done&&t.date<today?'due':''}">${esc(t.date.slice(5))}</small>`:''}${btn('편집','edit',{table:'tasks',id:t.id})}</div></div>`}
function goalBox(g){const p=finished(g),linked=lifeModel().goals.find(x=>x.id===g.id);return `<article class="goalbox" data-goal-card="${esc(g.id)}"><div class="goal-top">${tag(goalRole(g))}<span class="tone">${p.total&&p.done===p.total?'단계 완료':g.target||'진행 중'}</span></div><h3>${esc(g.title)}</h3><div class="progress"><i style="width:${p.total?p.done/p.total*100:0}%"></i></div><small>${p.total?p.done+'/'+p.total+' 단계':'준비 단계를 정해보세요'}</small><div class="next-action">다음 한 걸음 · ${esc(p.next?.title||'다음 행동 정하기')}</div><p class="muted">이번 주 예정 ${lifeSource().available?hoursText(linked?.planned||0):'미조회'} · 실제 ${hoursText(linked?.actual||0)}</p>${btn('목표 펼쳐보기 ↗','goal',{id:g.id})}</article>`}
function healthStats(){const recent=[...db.health].sort((a,b)=>b.date.localeCompare(a.date));const seven=recent.filter(h=>h.date>=addDays(today,-6)&&h.date<=today),sleep=seven.filter(h=>h.sleep!==''),weight=recent.find(h=>h.weight!==''),mood=recent.find(h=>h.mood);return `<div class="metric-grid">${[['수면 · 최근 7일',sleep.length?(sum(sleep,'sleep')/sleep.length).toFixed(1)+'h':'—',sleep.length?sleep.length+'일 기록 기준':'아직 기록 없음'],['활동 · 최근 7일',seven.filter(h=>num(h.minutes)>0).length+'일','시간을 입력한 날'],['운동 · 최근 7일',seven.filter(h=>h.exercise==='운동함').length+'일',seven.filter(h=>h.exercise).length+'일 여부 기록'],['음주 · 최근 7일',seven.filter(h=>h.drink==='마심').length+'일',seven.filter(h=>h.drink).length+'일 여부 기록'],['최근 컨디션',mood?.mood||'—',mood?.date||'선택 기록'],['최근 체중',weight?weight.weight+'kg':'—',weight?.date||'측정할 때만']].map(([a,b,c])=>`<div class="metric"><small>${a}</small><strong>${esc(b)}</strong><small>${esc(c)}</small></div>`).join('')}</div>`}

function orderedReviews(){return [...db.reviews].filter(r=>['result','obstacle','next','stop'].some(k=>r[k]?.trim())).sort((a,b)=>(b.savedAt||b.period).localeCompare(a.savedAt||a.period));}
function previousWeekly(period){return orderedReviews().filter(r=>r.kind==='주간'&&r.period<period).sort((a,b)=>b.period.localeCompare(a.period))[0];}
function reviewNext(r){return r.kind==='일간'?(r.experiment||''):r.next||'';}
function reviewAction(r){const task=db.tasks.find(t=>t.review===r.id);if(!reviewNext(r).trim())return '';return task?btn(task.done?'가져온 행동 완료 ✓':'할 일에 등록됨 ↗','go',{page:'work'},'linkbutton'):btn('이 행동을 할 일로 가져오기 ＋','review-task',{id:r.id},'linkbutton');}
function previousReviewContext(period){const last=previousWeekly(period);if(!last)return '';return `<div class="review-carry"><span class="eyebrow">지난번에 정한 다음 행동</span><p>${esc(last.next||'다음 행동은 적지 않았어요.')}</p><div class="goal-top"><small>${esc(last.period)} 주간 점검</small>${btn('지난 기록 열기','review-open',{id:last.id})}</div>${reviewAction(last)}<small class="carry-hint">지난 약속은 어떻게 되었나요? 이번 점검에 결과를 남겨보세요. 할 일로 가져와도 원문은 그대로 보존합니다.</small></div>`;}
function reviewDashboard(){const recent=orderedReviews().slice(0,3);return card('지난 돌아보기에서 이어가기',recent.length?`<div class="review-previews">${recent.map(r=>`<article class="review-preview"><div class="goal-top">${tag(r.kind)}<small>${esc(r.period)}</small></div>${r.result?`<span class="section-label">${r.kind==='일간'?'오늘의 이야기':'남긴 성과와 변화'}</span><p class="review-excerpt">${esc(r.result)}</p>`:''}${r.obstacle?`<p class="review-excerpt muted" style="margin-top:9px">${r.kind==='일간'?'오늘의 마음':'막혔던 것'} · ${esc(r.obstacle)}</p>`:''}${r.kind==='일간'&&r.learning?`<p class="review-excerpt muted" style="margin-top:9px">발견한 점 · ${esc(r.learning)}</p>`:''}${(r.kind==='일간'?(r.experiment||r.next):r.next)?`<div class="next-action"><b>${r.kind==='일간'?(r.experiment?'다음에 해볼 작은 시도':'내일의 나에게'):'그때 정한 다음 행동'}</b><p class="review-excerpt">${esc(r.kind==='일간'?(r.experiment||r.next):r.next)}</p></div>`:''}${r.stop?`<p class="review-excerpt muted" style="margin-top:9px">${r.kind==='일간'?'고마웠던 순간':'줄이거나 미룰 것'} · ${esc(r.stop)}</p>`:''}<div class="review-links">${btn('기록 전체 열기 ↗','review-open',{id:r.id},'linkbutton')}${reviewAction(r)}</div><small>${r.savedAt?'최근 저장 '+esc(new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(r.savedAt))):'기존 저장 기록'}</small></article>`).join('')}</div><p class="muted" style="margin-top:15px">최근 저장한 점검 최대 3개 · 원문은 기간별로 보관되며 수정 내용도 여기에 반영됩니다.</p>`:empty('돌아보기에서 남긴 성과·다음 행동이 여기에 표시됩니다.<br>지난 기록을 다시 읽고 이번 주 실행으로 이어가세요.',btn('첫 돌아보기 작성','go',{page:'review'},'outline')),btn('전체 기록 ↗','go',{page:'review'}));}


function lifeSource(){return window.HaruCalendar?.dashboardSnapshot?.()||{connected:false,available:false,tasksAvailable:false,events:[],tasks:[]}}
let lifeCache=null;
function lifeModel(){const source=lifeSource(),key=[iso(),Math.floor(Date.now()/60000),source.revision,source.available,source.tasksAvailable,source.connected].join('|');if(lifeCache?.state===db&&lifeCache.key===key)return lifeCache.value;const value=window.HaruLifeOverview.project(db,source,iso());lifeCache={state:db,key,value};return value;}
function linkedTaskRow(t){return t.origin==='local'?taskRow(t,true):`<div class="home-linked-task"><div><b>${esc(t.title)}</b><small>Google 자동 표시 · ${t.done?'완료':'미완료'}${t.date?' · '+esc(t.date):''}</small></div><button class="linkbutton" data-action="review-google-task" data-key="${esc(t.key)}">검토·수정</button></div>`}
function homeOverview(){const m=lifeModel(),s=lifeSource(),steps=m.allTasks.filter(t=>t.goal&&find('goals',t.goal)),diaries=db.reviews.filter(r=>r.kind==='일간'&&r.period>=m.start&&r.period<=iso()&&r.result.trim()).length;const tiles=[['업무·할 일',`${m.done} / ${m.tasks.length}`,`완료 / 전체 기간 · Google 자동 표시 ${m.tasks.filter(t=>t.origin==='google').length}개 · 분류 대기 ${m.unknownTasks.length}개${s.tasksAvailable?(s.tasksPartial?' · 일부 조회':''):' · Google 미조회'}`,'work'],['목표 준비 단계',`${steps.filter(t=>t.done).length} / ${steps.length}`,'Google 연결 단계 포함 · 목표 달성과는 구분','goals'],['이번 주 시간',s.available?'예정 '+hoursText(m.metrics.plannedMinutes).replace(' ','\u00a0'):s.status==='loading'?'일정 조회 중':'예정 미조회','확인한 실제 '+hoursText(m.metrics.recordMinutes)+(s.partial?' · 일부 캘린더 조회':''),'weekly'],['이번 주 일기',diaries+'일','오늘까지 쓴 일기','daily']];return `<section class="overview" aria-label="전체 현황 요약"><div class="overview-label"><span class="eyebrow">MY LIFE OVERVIEW</span><small>Google 조회와 내 기록 자동 연결 · 예정/실제 구분</small></div><div class="overview-grid">${tiles.map(([label,value,sub,page])=>`<button class="overview-tile" data-action="${page==='weekly'?'open-time':page==='daily'?'daily-open':'go'}" data-page="${page}"><span>${label}</span><strong>${esc(value)}</strong><small>${esc(sub)}</small></button>`).join('')}</div></section>`}
function homeWorkSummary(){const m=lifeModel(),s=lifeSource();return card('업무 현황',m.roles.map(({role:r,tasks,events,actual})=>`<article class="home-work-row"><div class="goal-top"><b>${esc(r.name)} ${tag(r.kind)}</b><small>${tasks.filter(t=>t.done).length}/${tasks.length} 완료</small></div><p>이번 주 일정 ${s.available?events.length+'개':'미조회'} · 실제 기록 ${hoursText(actual)}</p>${tasks.find(t=>!t.done)?linkedTaskRow(tasks.find(t=>!t.done)):'<p class="muted">새로운 다음 행동을 정해보세요.</p>'}</article>`).join('')+`${m.unknownEvents.some(e=>e.calendarName.trim()==='업무')?`<article class="home-work-row"><b>업무 캘린더 · 회사/프로젝트 미지정</b><p>이번 주 ${m.unknownEvents.filter(e=>e.calendarName.trim()==='업무').length}개 일정 자동 연결</p><button class="linkbutton" data-gcal="settings">기본 활동·목표 정하기</button></article>`:''}<p class="muted">활동 미지정: 할 일 ${m.unknownTasks.length}개 · 일정 ${s.available?m.unknownEvents.length+'개':'미조회'}. 회사·프로젝트 분류는 연결 설정에서 한 번 정하면 유지됩니다.</p>`,btn('업무 전체·분류 ↗','go',{page:'work'}))}
function homeTimeSummary(){const m=lifeModel(),s=lifeSource();return card('이번 주 예정과 실제',`<div class="overview-time-grid">${[['캘린더 예정 · 자동',s.available?hoursText(m.metrics.plannedMinutes):'미조회'],['지난 일정 기준 추정',s.available?hoursText(m.elapsedMinutes):'미조회'],['내가 확인한 실제 기록',hoursText(m.metrics.recordMinutes)]].map(([label,value])=>`<div><small>${label}</small><strong>${value}</strong></div>`).join('')}</div><p class="muted">${m.start} ~ ${addDays(m.end,-1)} · 예정·추정은 겹침 제외, 메모·종일 시간 제외. 실제와 합산하지 않습니다.</p>${m.pending.slice(0,3).map(e=>`<div class="home-linked-task"><div><b>${esc(e.title)}</b><small>${esc(e.day)} · ${esc(e.calendarName)}</small></div><button class="linkbutton" data-gcal="dashboard-event" data-key="${esc(e.key)}">실제 시간 검토</button></div>`).join('')}`,btn('시간 분석 ↗','open-time'))}
function workGooglePanel(){const m=lifeModel(),s=lifeSource(),newTasks=m.tasks.filter(t=>t.origin==='google'||t.sourceUpdate);return card('자동 연결된 업무 · 검토와 분류',`<p class="muted">Google Tasks ${s.tasksAvailable?(s.tasksPartial?'일부 조회':'조회 완료'):'미조회'} · 완료 항목 포함. 내 기록과 구글 식별자로 중복을 제거하고, 내가 수정한 내용은 유지합니다.</p>${newTasks.slice(0,10).map(t=>t.sourceUpdate?`<div class="home-linked-task"><b>${esc(t.title)}</b><button class="linkbutton" data-action="review-google-task" data-key="${esc(t.googleTaskKey)}">Google 변경 검토</button></div>`:linkedTaskRow(t)).join('')||'<p class="muted">새로 검토할 항목이 없습니다.</p>'}<p class="muted">미지정 할 일 ${m.unknownTasks.length}개 · 이번 주 활동 미지정 일정 ${s.available?m.unknownEvents.length:'미조회'}개</p><div class="calendar-controls"><button class="linkbutton" data-gcal="settings">캘린더 활동·목표 연결</button><button class="linkbutton" data-gcal="task-lists">Tasks 활동·목표 연결</button></div>`)}
function refreshLifeOverview(){for(const [selector,fn] of [['[data-life-overview]',homeOverview],['[data-home-work]',homeWorkSummary],['[data-home-time]',homeTimeSummary],['[data-work-google]',workGooglePanel]]){const el=document.querySelector(selector);if(el)el.innerHTML=fn()}for(const el of document.querySelectorAll('[data-goal-card]')){const g=find('goals',el.dataset.goalCard);if(g)el.outerHTML=goalBox(g)}}

let calendarTab='agenda',selectedTimeDay=today,timeMonthDraft=null;
const hoursText=minutes=>{const total=Math.max(0,Math.round(minutes)),h=Math.floor(total/60),m=total%60;return (h?h+'시간':'')+(m||!h?(h?' ':'')+m+'분':'');};
function timeAnalytics(){const source=window.HaruCalendar?.snapshot()||{start:week,end:addDays(week,7),events:[],available:false,partial:false};const data=window.HaruTimeStats.analyze({logs:db.timeLogs,planned:source.available?source.events:[],start:source.start,end:source.end,now:Date.now()});if(!data.days.some(d=>d.date===selectedTimeDay))selectedTimeDay=data.days.find(d=>d.date===iso())?.date||data.days[0].date;const day=data.days.find(d=>d.date===selectedTimeDay);return `<div class="toolbar">${[['today','오늘'],['week','이번 주'],['month','이번 달'],['previous-month','지난 달']].map(([range,label])=>btn(label,'time-range',{range},'chip '+(source.range===range?'on':''))).join('')}</div><form id="time-month-form" class="diary-date"><label for="time-month">다른 달 보기</label><input id="time-month" type="month" name="month" min="1900-01" max="2099-12" value="${source.start.slice(0,7)}" required><button class="outline">조회</button></form><p class="muted" style="margin-bottom:18px">${source.start} ~ ${addDays(source.end,-1)} · 한국 시간 기준</p><div class="time-metric-grid">${[['기록일 기준 실제 분 합계',hoursText(data.recordMinutes),data.recordCount+'건 · 겹치는 기록이 있을 수 있음'],['시각 확인분 · 겹침 제외',hoursText(data.confirmedMinutes),'실제 시작·종료를 확인한 구간의 합집합'],['캘린더 예정 · 겹침 제외',source.available?hoursText(data.plannedMinutes):source.status==='loading'?'불러오는 중':source.connected?'조회 확인 필요':'미연결',source.partial?'일부 캘린더만 조회됨':'종일 제외 · 실제 시간에 합산하지 않음'],['분만 기록 · 시각 미확인',hoursText(data.unplacedMinutes),'시작·종료 위치를 추정하지 않음']].map(([a,b,c])=>`<div class="metric"><small>${a}</small><strong>${b}</strong><small>${c}</small></div>`).join('')}</div><div class="notice" style="margin-top:15px">계획과 실제를 구분합니다. 시각이 확인되지 않은 구간에는 수면·휴식·분만 기록한 활동도 포함될 수 있습니다. 낭비나 비생산적인 시간이라는 뜻은 아닙니다.${data.overlapMinutes?'<br>실제 기록의 겹침 '+hoursText(data.overlapMinutes)+'을 발견했습니다. 분 합계와 겹침 제외 시간을 비교해보세요.':''}</div>${card('날짜별 나의 시간',`<div class="time-days">${['월','화','수','목','금','토','일'].map(d=>`<span class="time-week-label">${d}</span>`).join('')}${Array.from({length:(new Date(source.start+'T12:00:00+09:00').getUTCDay()+6)%7},()=>'<span aria-hidden="true"></span>').join('')}${data.days.map(d=>`<button type="button" class="time-day ${d.date===selectedTimeDay?'selected':''}" data-action="time-day" data-day="${d.date}"><b>${d.date.slice(5)}</b><span>기록 ${hoursText(d.recordMinutes)}</span><small>시각 확인 ${hoursText(d.confirmedMinutes)}</small><small>${source.available?'예정 '+(d.planned.length+d.allDayCount)+'건':'예정 미조회'}</small></button>`).join('')}</div>`)}<div class="two">${card('활동별 시간 배분',data.roles.length?data.roles.map(r=>`<div class="list-card"><div class="goal-top"><b>${esc(byName('roles',r.role,'미지정'))}</b><small>${hoursText(r.minutes)} · ${data.recordMinutes?Math.round(r.minutes/data.recordMinutes*100):0}%</small></div><div class="progress"><i style="width:${data.recordMinutes?r.minutes/data.recordMinutes*100:0}%"></i></div></div>`).join('')+'<p class="muted">기록일 기준 분 합계를 분모로 사용합니다. 여러 활동이 겹치면 하루 실제 경과 시간보다 클 수 있습니다.</p>':'<p class="empty">확인해서 저장한 실제 시간 기록이 없습니다.</p>')}${card('시간 구간의 확인 상태',row('<small>겹친 실제 기록</small>',`<b>${hoursText(data.overlapMinutes)}</b>`)+row('<small>경과한 시간 중 시각 미확인</small>',`<b>${hoursText(data.gapMinutes)}</b>`)+`<p class="muted" style="margin-top:12px">미래 시간은 미기록으로 계산하지 않습니다. 건강·관계 기록을 시간 기록에 다시 더하지도 않습니다.</p>`)}</div>${card(esc(day.date)+' · 예정과 실제 타임라인',dayTimeline(day))}`;}
function dayTimeline(day){const T=window.HaruTimeStats,start=T.stamp(day.date),fmt=stamp=>new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(stamp));const lane=(entry,kind)=>`<div class="time-lane"><div class="time-lane-label">${esc(entry.title)}<small>${fmt(entry.start)} ~ ${fmt(entry.end)}</small></div><div class="time-track"><${kind==='actual'?'button':'span'} ${kind==='actual'?`type="button" data-action="edit" data-table="timeLogs" data-id="${esc(entry.id)}"`:''} class="time-block ${kind}" style="left:${(entry.start-start)/864000}%;width:${Math.max(.3,(entry.end-entry.start)/864000)}%" title="${esc(entry.title)} · ${fmt(entry.start)} ~ ${fmt(entry.end)}" aria-label="${esc(entry.title)} · ${fmt(entry.start)} ~ ${fmt(entry.end)}"></${kind==='actual'?'button':'span'}></div></div>`;return `<div class="time-timeline-scroll"><div class="time-timeline"><div class="time-lane"><div></div><div class="time-ticks"><span>00시</span><span>06시</span><span>12시</span><span>18시</span><span>24시</span></div></div><h3>Google 예정</h3>${day.planned.map(e=>lane(e,'planned')).join('')||'<p class="muted">조회한 시간 지정 일정이 없어요.</p>'}${day.allDayCount?`<p class="muted">종일 일정 ${day.allDayCount}건 · 시간 합산 제외</p>`:''}<h3 style="margin-top:22px">확인한 실제 구간</h3>${day.actual.map(e=>lane(e,'actual')).join('')||'<p class="muted">실제 시작·종료까지 확인한 구간은 없어요. 예정 위치를 실제 위치로 복사하지 않습니다.</p>'}</div></div><details class="diary-extra"><summary>경과한 구간 중 시각이 확인되지 않은 곳 · ${hoursText(day.gapMinutes)}</summary>${day.gaps.map(([a,b])=>`<div class="row"><span>${fmt(a)} ~ ${fmt(b)}</span><small>${hoursText((b-a)/60000)}</small></div>`).join('')||'<p class="muted">경과한 구간 중 시각 미확인 부분이 없습니다.</p>'}<p class="muted">활동이 없었다는 뜻이 아닙니다. 수면·휴식·분만 기록한 활동은 여기에도 포함될 수 있어요.</p></details>${day.unplaced.length?'<h3>시간대 위치를 정하지 않은 기록</h3>'+day.unplaced.map(l=>row(`${esc(l.title)}<p>${esc(byName('roles',l.role,'미지정'))} · ${esc(l.minutes)}분</p>`,btn('시각 확인','edit',{table:'timeLogs',id:l.id}))).join(''):''}`;}
function refreshTimeAnalytics(){const root=document.querySelector('[data-time-analytics]');if(root&&window.HaruTimeStats){const focused=document.activeElement?.id==='time-month';root.innerHTML=timeAnalytics();const input=root.querySelector('#time-month');if(input&&timeMonthDraft!==null)input.value=timeMonthDraft;if(input&&focused)input.focus();}}

function calendarPage(){return heading('MY CALENDAR & TIME','내 캘린더와 시간 분석','전체 일정과 실제 기록을 구분하고, 활동별·날짜별로 자세히 돌아보세요.')+'<div class="toolbar">'+btn('일정·검토','calendar-tab',{tab:'agenda'},'chip '+(calendarTab==='agenda'?'on':''))+btn('상세 시간 분석','calendar-tab',{tab:'time'},'chip '+(calendarTab==='time'?'on':''))+'</div>'+(calendarTab==='time'?'<div data-time-analytics></div><details class="card"><summary>Google 일정 조회·연결 설정</summary><div data-calendar-slot="full"></div></details>':'<div data-calendar-slot="full"></div>');}
function home(){const focus=db.focus.find(f=>f.period===week),focusTask=find('tasks',focus?.task),focusGoal=find('goals',focusTask?.goal);const currentReview=db.reviews.find(r=>r.kind==='주간'&&r.period===week);const reminders=[...db.tasks.filter(t=>!t.done&&t.date).map(t=>({title:t.title,date:t.date,kind:'할 일',action:'edit',table:'tasks',id:t.id})),...db.issues.filter(i=>!i.done&&i.date).map(i=>({title:i.title,date:i.date,kind:'관계',action:'edit',table:'issues',id:i.id})),...db.loans.filter(l=>l.date).map(l=>({title:l.name+' 납부 확인',date:l.date,kind:'대출',action:'edit',table:'loans',id:l.id})),...db.decisions.filter(d=>d.date&&!d.actual).map(d=>({title:d.title+' 결과 점검',date:d.date,kind:'결정',action:'edit',table:'decisions',id:d.id}))].sort((a,b)=>a.date.localeCompare(b.date));const loan=sum(db.loans,'balance'),investment=sum(db.investments,'value'),received=sum(db.incomes.filter(i=>i.done&&i.date.startsWith(today.slice(0,7))),'amount');const relationMinutes=sum(db.moments.filter(m=>m.date>=week&&m.date<=today),'minutes');return heading('YOUR LIFE, AT A GLANCE','좋은 하루예요. 오늘은 무엇이 중요한가요?','많이 채우기보다, 나에게 중요한 일을 한 걸음씩.',!DEMO?'<a class="outline" href="?demo=1" style="text-decoration:none">예시로 둘러보기 ↗</a>':'')+`<div class="home-layout"><div><div data-calendar-slot="home"></div><section class="hero"><div><span class="eyebrow">이번 주 한 걸음</span><h2>${esc(focusTask?.title||'이번 주, 가장 중요한 한 걸음은?')}</h2><p>${focusTask?esc((focusGoal?goalRole(focusGoal)+' → '+focusGoal.title:'나의 계획')+(focusTask.done?' · 완료했어요':'')):'급하지 않아도 중요한 일 하나를 먼저 정해보세요.'}</p></div>${btn(focusTask?'한 걸음 바꾸기':'이번 주 행동 선택','focus',{},'primary')}</section><div data-life-overview>${homeOverview()}</div><div class="two"><div data-home-work>${homeWorkSummary()}</div><div data-home-time>${homeTimeSummary()}</div></div>${dailyHomeCard()}<div class="two">${card('이번 주',`<div class="weekstrip">${['월','화','수','목','금','토','일'].map((d,i)=>{const day=addDays(week,i);return `<div class="weekday ${day===today?'on':''}">${d}<b>${Number(day.slice(8))}</b><span class="week-dot" style="opacity:${db.notes.some(n=>n.date===day)?1:.15}"></span></div>`}).join('')}</div><p class="muted">이번 주 기록 ${db.notes.filter(n=>n.date>=week&&n.date<=today).length}건 · 점은 기록을 남긴 날</p><div class="prompt" style="margin-top:15px">이번 주 질문<br><b>중요하지만 계속 뒤로 밀리는 일은 무엇인가요?</b></div>${previousReviewContext(week)}<form id="weekNote"><input name="next" aria-label="이번 주 점검 한 줄" class="inline-input" value="${esc(currentReview?.next||'')}" placeholder="한 줄이면 충분합니다."><div style="text-align:right;margin-top:6px"><button class="linkbutton">주간 점검 저장</button></div></form>`,btn('돌아보기 ↗','go',{page:'review'}))}${card('곧 챙길 것',reminders.length?reminders.slice(0,5).map(r=>row(`${tag(r.kind,r.kind==='관계'?'purple':'')} <span style="font-size:11px">${esc(r.title)}</span>`,btn(r.date.slice(5),r.action,{table:r.table,id:r.id},r.date<today?'quiet due':'quiet'))).join(''):empty('다가오는 일이 아직 없어요.<br>할 일·관계 이슈·납부일·결정 점검일을 모아 보여줍니다.'),btn('할 일 ＋','edit',{table:'tasks'}))}</div>${reviewDashboard()}${card('역할별 목표와 버킷리스트',db.goals.length?`<div class="goal-grid">${db.goals.slice(0,6).map(goalBox).join('')}</div>`:`<div class="goal-grid">${db.roles.slice(0,5).map(r=>`<article class="goalbox">${tag(r.name)}<h3>${esc(r.kind==='삶'?'어떤 삶을 살고 싶나요?':'이 역할에서 남기고 싶은 성과는?')}</h3><p>${r.name==='가족·관계'?'함께할 시간과 필요한 대화':r.name==='나 자신'?'건강, 배움, 이루고 싶은 경험':'역할에 맞는 목표와 다음 행동을 정해요.'}</p>${btn('목표 만들기 ＋','new-goal',{role:r.id})}</article>`).join('')}</div>`,btn('꿈·5년 뒤의 나 ↗','go',{page:'goals'}))}</div><div class="home-rail">${card('돈',`<span class="muted">등록한 투자 평가액</span><div class="big">${db.investments.length?money(investment):'아직 미등록'}</div><p class="muted">평가일은 투자별로 확인해요.</p><p class="muted" style="margin-top:8px">${db.investments.length?'등록 투자 평가손익 '+money(investment-sum(db.investments,'principal')):'투자·대출을 등록하면 현황이 표시됩니다.'}</p>${row('<small>대출 잔액</small>',`<b>${db.loans.length?money(loan):'—'}</b>`)}${row('<small>월 상환액 합계</small>',`<b>${db.loans.length?money(sum(db.loans,'monthly')):'—'}</b>`)}${incomeMini()}<p class="muted" style="margin-top:10px">등록 투자 ${db.investments.length}건 · 대출 ${db.loans.length}건 · 지출 기록 없음</p>`,btn('관리 ↗','go',{page:'money'}))}${moneyGoalsHome()}${card('건강',healthStats(),btn('기록 ＋','edit',{table:'health'}))}${relationshipHome()}${card('나의 원칙',`<p style="font-size:12px">${esc(db.profile.principle||'나에게 중요한 기준 한 줄을 남겨보세요.')}</p><p class="muted" style="margin-top:12px">결정할 때 돌아올 나만의 기준</p>`,btn('편집','vision'), 'summary-green')}</div></div>`}
function notesPage(){return heading('CAPTURE, THEN CLARIFY','기록은 가볍게, 다시 찾기는 쉽게','분류를 위해 멈추지 않도록. 한 줄부터 시작해요.',btn('＋ 기록','edit',{table:'notes'},'outline'))+`<input class="inline-input" id="searchNotes" aria-label="기록 검색" placeholder="내용이나 역할로 검색" style="margin:0 0 20px"><div id="noteResults">${noteList(db.notes)}</div>`}
function noteList(notes){return card('나의 기록',notes.length?[...notes].sort((a,b)=>b.date.localeCompare(a.date)).map(n=>`<article class="note"><p>${esc(n.text)}</p><div class="goal-top"><span class="muted">${esc(n.date)} · ${esc(byName('roles',n.role,'자유 기록'))}</span>${btn('편집','edit',{table:'notes',id:n.id})}</div></article>`).join(''):empty('아직 기록이 없어요. 떠오른 생각을 한 줄 남겨보세요.'))}
function goalsPage(){const filtered=db.goals.filter(g=>filter==='전체'||g.kind===filter);return heading('DIRECTION BEFORE SPEED','목표와 꿈, 나의 방향','하고 싶은 경험도, 남기고 싶은 성과도. 나에게 중요한 이유부터.',btn('＋ 목표·버킷','edit',{table:'goals'},'outline'))+`<div class="content-grid"><div><div class="toolbar">${['전체','장기 목표','올해 목표','버킷리스트'].map(f=>btn(f,'filter',{value:f},'chip '+(filter===f?'on':''))).join('')}</div>${filtered.length?`<div class="goal-grid">${filtered.map(goalBox).join('')}</div>`:card('아직 정하지 않아도 괜찮아요',empty('목표를 하나 정하고, 필요한 준비를 작은 단계로 나눠보세요.',btn('첫 목표 만들기','edit',{table:'goals'},'outline'))) }</div><div>${card('5년 뒤의 나',`<p style="font-size:12px;white-space:pre-wrap">${esc(db.profile.vision||'무슨 일을 하며, 누구와 어떤 하루를 보내고 싶나요?')}</p>`,btn('편집','vision'))}${card('목표를 행동으로 바꾸기','<div class="stack"><p>① 왜 내가 원하는가?</p><p>② 이루면 어떤 모습일까?</p><p>③ 무엇이 나를 막을까?</p><p>④ 그 상황에서 무엇을 할까?</p></div><div class="prompt" style="margin-top:16px">꿈은 자유롭게. 행동은 구체적으로.<br>“일요일 저녁이면 여행 예산을 10분 정리한다.”</div>',btn('설계 근거 ↗','guide'))}</div></div>`}

function fixedAlbaFee(log){return window.HaruIncomeFormat.parseAlbaTitle(log.googleOriginalTitle||log.title).amountWon;}
function partTimeSummary(){const entries=db.timeLogs.filter(t=>t.workKind==='알바'),month=entries.filter(t=>t.date.startsWith(today.slice(0,7))),priced=month.filter(t=>fixedAlbaFee(t)===null&&t.hourlyRate!==undefined&&t.hourlyRate!==''&&Number.isFinite(Number(t.hourlyRate))&&Number(t.hourlyRate)>=0),estimate=priced.reduce((a,t)=>a+Math.round(num(t.minutes)/60*num(t.hourlyRate)),0);return card('알바 기록',`<div class="parttime-metrics"><div><small>이번 달 확인한 근무시간</small><strong>${(sum(month,'minutes')/60).toLocaleString('ko-KR',{maximumFractionDigits:1})}h</strong></div><div><small>시급 입력분의 예상 금액</small><strong>${priced.length?money(estimate):'미입력'}</strong></div></div><p class="muted">${month.length}건 중 시급 계산 ${priced.length}건 기준 · 제목의 총액 표기는 시급 예상에서 제외 · 실제 입금 아님</p>${entries.length?[...entries].sort((a,b)=>b.date.localeCompare(a.date)).map(t=>`<div class="list-card"><div class="goal-top"><h3>${esc(t.employer||t.title)}</h3>${btn('편집','edit',{table:'timeLogs',id:t.id})}</div><p class="muted">${esc(t.date)} · ${esc(t.minutes)}분 · ${esc(t.title)}</p><p class="muted">${fixedAlbaFee(t)!==null?'제목의 총액 '+money(fixedAlbaFee(t))+' · 수입 확인은 별도':t.hourlyRate!==undefined&&t.hourlyRate!==''?'시급 '+money(t.hourlyRate)+' · 예상 '+money(Math.round(num(t.minutes)/60*num(t.hourlyRate))):'시급 미입력'}</p>${btn('수입으로 검토','income-from-time',{id:t.id},'linkbutton')}</div>`).join(''):'<p class="empty">캘린더에서 끝난 알바 일정을 확인하거나 근무시간을 직접 남겨보세요.</p>'}`,btn('알바 기록 ＋','new-parttime'));}

function workPage(){const workRoles=db.roles.filter(r=>r.kind!=='삶'),selected=workRoles.filter(r=>filter==='전체'||r.kind===filter),planned=sum(workRoles,'hours');return heading('MANAGE YOUR CONTRIBUTION','일과 역할','본업과 사이드프로젝트를 구분하고, 내가 기여할 성과를 명확하게.',btn('＋ 활동 추가','edit',{table:'roles'},'outline'))+`<div data-work-google>${workGooglePanel()}</div><div class="toolbar">${['전체',...new Set(workRoles.map(r=>r.kind))].map(f=>btn(f,'filter',{value:f},'chip '+(filter===f?'on':''))).join('')}</div><div class="content-grid"><div>${selected.map(r=>card(`${tag(r.kind)} &nbsp; ${esc(r.name)}`,`<p class="muted">내 역할 · ${esc(r.role||'미정')}</p><p style="font-size:12px;margin-top:12px">${esc(r.purpose||'이 역할에서 어떤 기여를 하고 싶은지 적어보세요.')}</p><div class="section-label">연결된 목표</div>${db.goals.filter(g=>g.role===r.id).map(g=>row(esc(g.title),btn('보기','goal',{id:g.id}))).join('')||'<p class="muted">아직 연결된 목표가 없어요.</p>'}<div class="section-label">다음 행동</div>${db.tasks.filter(t=>t.role===r.id).map(t=>taskRow(t)).join('')||'<p class="muted">필요한 행동 하나부터 추가해보세요.</p>'}<div style="margin-top:12px;display:flex;gap:15px">${btn('＋ 할 일','new-task',{role:r.id},'linkbutton')}${btn('＋ 목표','new-goal',{role:r.id},'linkbutton')}</div>`,btn('편집','edit',{table:'roles',id:r.id}))).join('')||card('새로운 활동',empty('본업, 부업, 개인사업 등 활동을 추가할 수 있어요.'))}${partTimeSummary()}${card('역할 미지정 할 일',db.tasks.filter(t=>!t.role||!find('roles',t.role)).map(t=>taskRow(t)).join('')||'<p class="muted">미지정 할 일이 없어요.</p>',btn('추가 ＋','edit',{table:'tasks'}))}</div><div>${card('내 시간의 여유',`<div class="big">${planned} <small>시간</small></div><p class="muted">활동별 주간 계획 시간 합계<br>실제 사용 시간이나 여유 시간 계산값은 아닙니다.</p><div class="prompt" style="margin-top:16px">이 계획과 함께 가족, 건강, 휴식도 지킬 수 있나요?<br>이번 주 무엇을 미룰지도 정해보세요.</div>`)}${card('시간을 알아야 바꿀 수 있어요','<p style="font-size:12px">중요한 일을 했던 시간이나 예상보다 오래 걸린 일을 짧게 남겨보세요. 주간 점검에서 실제 흐름을 확인합니다.</p>',btn('시간 기록 ＋','edit',{table:'timeLogs'}))}</div></div>`}
const incomeFormat=()=>window.HaruIncomeFormat;
const incomeSummary=month=>incomeFormat().summarize(db.incomes,month);
let incomeMonth=today.slice(0,7),incomeEditing=null;
function incomeMini(){const s=incomeSummary(today.slice(0,7));return row('<small>이번 달 확정 추가 수입</small>',`<b>${s.earnedCount?money(s.earned):'—'}</b>`)+row('<small>이번 달 실제 입금</small>',`<b>${s.receivedCount?money(s.received):'—'}</b>`);}
function incomeLedger(){const f=incomeFormat(),stats=incomeSummary(incomeMonth),rows=db.incomes.filter(r=>r.date?.slice(0,7)===incomeMonth||f.receipt(r)?.date.slice(0,7)===incomeMonth).sort((a,b)=>b.date.localeCompare(a.date));const year=incomeMonth.slice(0,4);return card('월별 추가 알바 수입',`<form id="income-month-form" class="diary-date"><label for="income-month">확인할 달</label><input id="income-month" type="month" name="month" value="${incomeMonth}" required><button class="outline">조회</button></form><div class="metric-grid"><div class="metric"><small>수행월 기준 확정 수입</small><strong>${money(stats.earned)}</strong><small>${stats.earnedCount}건 · 월급 등 미등록 수입 제외</small></div><div class="metric"><small>입금월 기준 실제 입금</small><strong>${money(stats.received)}</strong><small>${stats.receivedCount}건 · 입금 확인분만</small></div><div class="metric"><small>선택한 달의 예정 수입</small><strong>${money(stats.expected)}</strong><small>확정 합계에서 제외 · ${stats.expectedCount}건</small></div><div class="metric"><small>수행월 확정분 중 미입금</small><strong>${money(stats.unpaid)}</strong><small>입금 완료로 표시하지 않은 ${stats.unpaidCount}건</small></div></div><p class="muted" style="margin-top:14px">[알바] … (50) → 총 50만원을 제안하며, 확인 후에만 합산합니다. 수행월과 실제 입금월은 다를 수 있습니다. 시급 예상 금액과 자동 합산하지 않습니다.</p>${rows.length?rows.map(r=>{const receipt=f.receipt(r);return `<article class="list-card"><div class="goal-top"><h3>${esc(r.title)}</h3>${btn('수입 검토·수정','income-edit',{id:r.id})}</div><div class="goal-top"><b>${money(r.amount)}</b>${tag(f.stage(r)==='earned'?'수익 확정':'예정',f.stage(r)==='earned'?'green':'amber')}</div><p class="muted" style="margin-top:9px">수행일 ${esc(r.date)} · ${esc(byName('roles',r.role,'활동 미지정'))}</p><p class="muted">${receipt?'입금 완료 '+esc(receipt.date)+' · 실제 '+money(receipt.amount):'입금 미확인'}${r.googleIncomeKey?' · 캘린더에서 확인':''}</p>${r.note?`<p class="review-excerpt muted" style="margin-top:7px">${esc(r.note)}</p>`:''}</article>`;}).join(''):'<p class="empty">이 달의 등록 수입이 없습니다. 캘린더의 [알바] 일정에서 수입을 확인하거나 직접 추가하세요.</p>'}<details class="diary-extra"><summary>${year}년 월별 집계 보기</summary><div class="income-table"><div class="income-table-row"><b>월</b><b>확정 수입</b><b>실제 입금</b></div>${Array.from({length:12},(_,i)=>{const month=year+'-'+String(i+1).padStart(2,'0'),s=incomeSummary(month);return `<div class="income-table-row">${btn((i+1)+'월','income-month',{month},'linkbutton')}<span>${money(s.earned)}</span><span>${money(s.received)}</span></div>`;}).join('')}</div></details><p class="muted">지출 가계부는 없습니다. 입금액은 한 수입의 최종 입금액 한 건을 기록하며 세전·세후·세금·분할입금 이력을 자동 추정하지 않습니다.</p>`,btn('수입 기록 ＋','income-new'));}
function incomeForm(values={},key){const bySource=values.googleIncomeKey?db.incomes.find(r=>r.googleIncomeKey===values.googleIncomeKey):null,existing=key?find('incomes',key):bySource;incomeEditing={id:existing?.id,source:{...values,...existing}};const data={title:'',amount:'',date:iso(),role:'',stage:'earned',note:'',...values,...existing};if(existing)data.stage=incomeFormat().stage(existing);const receipt=existing?incomeFormat().receipt(existing):null;
 modal('추가 알바 수입 확인',`<p class="intro">${values.googleOriginalTitle?`원본 일정: ${esc(values.googleOriginalTitle)}<br>`:''}${values.parsedAmountLabel?esc(values.parsedAmountLabel)+'<br>':''}금액·수행일·분류를 확인한 뒤 저장하세요. 시급이 아니라 이 건의 총 수입입니다.</p><form id="income-record-form">${field(def('title','수입 내용','text',{required:true,max:120}),data)}${field(def('amount','이 건의 총 수입 (원)','number',{required:true,min:0,max:incomeFormat().LIMIT,step:1}),data)}${field(def('date','수익 귀속일 · 업무를 수행한 날짜','date',{required:true}),data)}${field(def('role','관련 활동','select',{options:roleOptions(),blank:'미지정'}),data)}${field(def('stage','수입 상태','select',{options:[['expected','예정 · 확정 합계에서 제외'],['earned','수익 확정 · 수행월 합계에 반영']]}),data)}<details class="diary-extra" ${existing?.done?'open':''}><summary>실제 입금을 확인했을 때만 입력</summary><label class="check"><input type="checkbox" name="done" ${existing?.done?'checked':''}><span>이 건의 입금이 완료됐습니다.</span></label>${field(def('receivedDate','최종 입금일','date',{max:iso()}),{receivedDate:receipt?.date||iso()})}${field(def('receivedAmount','실제 입금된 금액 (원)','number',{min:0,max:incomeFormat().LIMIT,step:1}),{receivedAmount:receipt?.amount??data.amount})}<p class="muted">세금 공제 등으로 위의 수입 금액과 다르면 실제 입금액을 적습니다. 입금 완료를 선택하지 않으면 입금 합계에 포함하지 않습니다.</p></details>${field(def('note','메모 · 선택','textarea'),data)}<p id="income-error" class="error" role="alert"></p><div class="form-actions">${existing?btn('삭제','delete',{table:'incomes',id:existing.id},'delete'):''}${btn('취소','close')}<button class="primary">확인한 수입 저장</button></div></form>`);}
function incomeFromTime(key){const log=find('timeLogs',key);if(!log)return;const parsed=incomeFormat().parseAlbaTitle(log.googleOriginalTitle||log.title),known=parsed.amountWon!==null,estimated=log.hourlyRate!==undefined&&log.hourlyRate!==''?Math.round(num(log.minutes)/60*num(log.hourlyRate)):null;incomeForm({title:parsed.tagged?parsed.title:log.employer||log.title,amount:known?String(parsed.amountWon):estimated===null?'':String(estimated),date:log.date,role:log.role,stage:known?'earned':'expected',googleIncomeKey:log.googleEventKey||JSON.stringify(['timeLog',log.id]),sourceTimeLogId:log.id,googleOriginalTitle:log.googleOriginalTitle||'',parsedAmountLabel:known?'일정 제목의 총액을 가져왔습니다.':estimated!==null?'시급으로 계산한 예상값입니다. 실제 수입이 확정됐는지 확인해주세요.':''});}
function submitIncome(e){e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),amount=incomeFormat().knownAmount(data.amount),paid=e.target.done.checked,receivedAmount=paid?incomeFormat().knownAmount(data.receivedAmount):null;const validDate=d=>/^\d{4}-\d{2}-\d{2}$/.test(d||'')&&dayOfDate(d)===d;function dayOfDate(d){try{return iso(new Date(d+'T12:00:00+09:00'))}catch{return ''}}
 if(!data.title?.trim()||amount===null||!validDate(data.date)||!['earned','expected'].includes(data.stage)||(data.stage==='earned'&&data.date>iso())||(paid&&(!validDate(data.receivedDate)||data.receivedDate>iso()||receivedAmount===null))){$('#income-error').textContent='금액과 날짜를 확인해주세요. 미래 수행일은 예정으로, 입금 완료는 실제 입금일·금액을 함께 기록합니다.';return;}
 const record={...incomeEditing.source,title:data.title.trim(),amount:String(amount),date:data.date,role:data.role||'',stage:data.stage,done:paid,receivedDate:paid?data.receivedDate:'',receivedAmount:paid?String(receivedAmount):'',note:data.note||'',id:incomeEditing.id||id()};delete record.parsedAmountLabel;
 if(commit(n=>{const same=n.incomes.findIndex(r=>r.id===record.id||(record.googleIncomeKey&&r.googleIncomeKey===record.googleIncomeKey));if(same>=0)n.incomes[same]={...n.incomes[same],...record,id:n.incomes[same].id};else n.incomes.push(record);})){closeModal();}}

function moneyPlan(){return HaruMoneyGoals.read(db.profile)}
function updateMoneyPlan(edit,message){return commit(n=>{const plan=HaruMoneyGoals.read(n.profile);edit(plan);n.profile.moneyPlan=JSON.stringify(plan)},message)}
function moneyGoalForm(key,kind='purpose'){if(!key&&kind==='debt'&&!db.loans.length){modal('먼저 대출 현황을 등록해주세요',`<p class="intro">상환 목표는 등록한 대출 잔액과 연결합니다.</p>${btn('대출 등록','edit',{table:'loans'},'primary')}`);return;}const plan=moneyPlan(),g=plan.goals.find(g=>g.id===key)||{kind,source:kind==='debt'?'loan':'manual',link:kind==='debt'?db.loans[0]?.id:'',baseline:kind==='debt'?db.loans[0]?.balance:'',current:'0',asof:iso(),priority:'2'},sources=[['manual','직접 입력한 확보액'],...db.investments.map(i=>['investment:'+i.id,'투자 · '+i.name]),...db.loans.map(l=>['loan:'+l.id,'상환 · '+l.name])],data={...g,selection:g.source==='manual'?'manual':g.source+':'+g.link};modal(key?'자금 목표 편집':'자금 목표 만들기',`<p class="intro">목적 · 금액 · 날짜를 정하고, 실제 확보액만 확인해요. 지출 입력은 필요 없습니다.</p><form id="moneyGoalForm" data-id="${esc(key||'')}">${field(def('title','목표 이름','text',{required:true,max:120,placeholder:'예: 소득이 끊겨도 버틸 비상자금'}),data)}${field(def('kind','목적','select',{options:[['reserve','비상자금'],['purpose','목적자금 · 꿈'],['investment','장기 투자'],['debt','대출 상환']]}),data)}${field(def('target','목표 금액 (원) · 상환 목표는 줄일 금액','number',{required:true,min:1,step:1}),data)}${field(def('deadline','목표 날짜','date',{required:true}),data)}${field(def('selection','진행률 계산 기준','select',{options:sources}),data)}<p class="muted">투자를 연결하면 해당 평가액, 대출을 연결하면 시작 잔액에서 줄어든 금액을 사용합니다. 연결된 금액은 아래 직접 입력값을 대신합니다.</p><div id="money-manual-fields" ${g.source==='manual'?'':'hidden'}>${field(def('current','현재 확보액 (원)','number',{min:0,step:1}),data)}${field(def('asof','확보액 기준일','date',{max:iso()}),data)}</div><div id="money-loan-fields" ${g.source==='loan'?'':'hidden'}>${field(def('baseline','상환 시작 시점 대출 잔액 (원)','number',{min:1,step:1}),data)}<p class="muted">대출 잔액이 늘면 진행률이 낮아집니다. 새 대출·차환은 이 기준이 계속 맞는지 확인해주세요.</p></div><details><summary>내 실행 계획 (선택)</summary>${field(def('why','이 돈이 필요한 이유','textarea',{placeholder:'예: 수입이 불규칙해도 생활을 유지하기 위해'}),data)}${field(def('monthly','매월 실행할 금액 (원)','number',{min:0,step:1}),data)}${field(def('next','다음 행동 · 언제 실행할지','text',{max:250,placeholder:'예: 매월 입금 다음 날 30만원을 별도 계좌로 이체'}),data)}${field(def('priority','우선순위','select',{options:[['1','먼저'],['2','그다음'],['3','나중에']]}),data)}</details><p class="error" role="alert"></p><div class="form-actions">${key?btn('목표 삭제','money-goal-delete',{id:key},'delete'):''}${btn('취소','close')}<button class="primary">저장</button></div></form>`)}
function moneyGoalUpdate(key){const g=moneyPlan().goals.find(g=>g.id===key);if(!g)return;const s=HaruMoneyGoals.status(g,db,iso());if(g.source==='manual')modal('확보액 점검',`<p class="intro">${esc(g.title)} · 현재 잔액으로 바꿔 입력해요. 입금액을 누적하는 화면이 아닙니다.</p><form id="moneyCheckForm" data-id="${esc(key)}">${field(def('current','현재 확보액 (원)','number',{required:true,min:0,step:1}),g)}${field(def('asof','확보액 기준일','date',{required:true,max:iso(),value:iso()}),{})}${field(def('note','이번 점검에서 기억할 것 (선택)','textarea'),{})}<p class="error" role="alert"></p><div class="form-actions">${btn('취소','close')}<button class="primary">점검 저장</button></div></form>`);else modal('연결된 현황 점검',`<p class="intro">${esc(g.title)}</p><p>${s.known?money(Math.max(0,s.current))+' / '+money(s.target):'연결된 기록과 기준일을 확인해주세요.'}</p><p class="muted">원본 기준일 ${esc(s.asof||'미입력')} · 오늘의 시세로 갱신하지 않고, 등록된 값을 이력으로 남깁니다.</p>${s.known?btn('이 현황으로 점검 저장','money-goal-check',{id:key},'primary'):''}${btn('원본 현황 편집','edit',{table:g.source==='loan'?'loans':'investments',id:g.link})}`)}
function moneyCheckpoint(g,dbState){const s=HaruMoneyGoals.status(g,dbState,iso());if(!s.known)return;const entry={id:id(),reviewed:iso(),asof:s.asof,current:s.current,target:s.target,source:g.source,sourceName:g.source==='manual'?'직접 입력':(find(g.source==='loan'?'loans':'investments',g.link)?.name||''),baseline:g.baseline||'',note:g.checkNote||''};g.history=[...(Array.isArray(g.history)?g.history:[]),entry].slice(-120);delete g.checkNote;}
function moneyGoalBox(g,compact=false){const s=HaruMoneyGoals.status(g,db,iso()),history=Array.isArray(g.history)?g.history:[],latest=history.at(-1);return `<article class="goalbox money-goal"><div class="goal-top"><h3>${esc(g.title)}</h3>${tag(({reserve:'비상자금',purpose:'목적자금',investment:'장기 투자',debt:'상환'})[g.kind]||'목표')}</div><p>${s.known?`${money(Math.max(0,s.current))} / ${money(s.target)} · ${Math.round(s.percent)}%`:'현재 현황 확인 필요'}</p>${s.known?`<progress max="100" value="${s.percent}" aria-label="${esc(g.title)} 달성률">${Math.round(s.percent)}%</progress>`:''}<p class="muted">${esc(g.deadline)}까지${s.asof?' · 잔액 기준 '+esc(s.asof):''}</p>${s.known?`<p>남은 금액 <b>${money(s.remaining)}</b>${s.monthly!==null?' · 월 약 '+money(s.monthly):''}</p>`:''}${s.overdue&&s.remaining>0?'<p class="due">목표 날짜가 지났어요. 금액·기한·실행 계획을 다시 정해보세요.</p>':''}${s.stale?'<p class="due">기준일이 45일 이상 지났어요. 최근 현황을 확인해주세요.</p>':''}${s.missing?'<p class="due">연결한 기록이 삭제되었습니다. 목표를 편집해 다시 연결해주세요.</p>':''}${g.source==='loan'&&s.known&&s.current<0?'<p class="due">시작 시점보다 대출 잔액이 늘었습니다. 남은 금액에 증가분을 포함했습니다.</p>':''}${!compact?`<p class="muted">${esc(g.why||'목표의 이유는 필요할 때 추가하세요.')}</p>${g.monthly?`<p>내 월 실행 계획 ${money(g.monthly)}${s.monthly!==null&&Number(g.monthly)<s.monthly?' · 현재 필요액보다 적어요. 금액 또는 기한을 조정해보세요.':''}</p>`:''}<div class="next-action">${esc(g.next||'다음 행동 하나를 정해보세요.')}</div><div class="relation-actions">${btn('현황 점검','money-goal-update',{id:g.id})}${btn('편집','money-goal-edit',{id:g.id})}</div><details><summary>점검 이력 ${history.length}회${latest?' · 최근 '+esc(latest.reviewed):''}</summary>${history.length?[...history].reverse().map(h=>`<div class="list-card"><b>${esc(h.reviewed)}</b><p>${money(Math.max(0,Number(h.current)||0))} / 당시 목표 ${money(Number(h.target)||0)}</p><p class="muted">잔액 기준 ${esc(h.asof)} · ${esc(h.sourceName||'')} ${h.source==='loan'?'(상환 시작 '+money(h.baseline)+')':''} · ${esc(h.note||'')}</p></div>`).join(''):'<p class="muted">현황 점검을 저장하면 당시 금액이 남습니다.</p>'}</details>`:''}</article>`}
function moneyGoalsHome(){const goals=[...moneyPlan().goals].sort((a,b)=>Number(a.priority||2)-Number(b.priority||2));return card('나의 자금 목표',goals.length?moneyGoalBox(goals[0],true):'<p class="muted">돈으로 이루고 싶은 일 하나부터 정해보세요.</p>',btn(goals.length?'목표 전체 보기 ↗':'목표 만들기','go',{page:'money'}))}
function moneyMethods(){return `<details class="money-methods"><summary>어떤 방법인가요? · 근거와 작성 예시</summary><div class="stack"><article><h3>1. 목적 · 금액 · 날짜 · 다음 행동</h3><p>미국 소비자금융보호국(CFPB)의 Your Money, Your Goals는 SMART 목표, 실행 계획, 목표 재검토 도구를 제공합니다. 막연한 ‘부자 되기’를 확인 가능한 행동으로 바꾸는 데 활용합니다.</p><div class="prompt">예: ‘내년 6월까지 이사자금 1,200만원. 확보액 300만원. 입금 다음 날 별도 계좌로 100만원 이체.’</div><a href="https://www.consumerfinance.gov/consumer-tools/educator-tools/your-money-your-goals/toolkit/" target="_blank" rel="noopener noreferrer">CFPB · 목표·저축·부채 도구 원문 ↗</a></article><article><h3>2. 비상자금은 필요와 접근성을 기준으로</h3><p>CFPB는 비상자금을 예상하지 못한 지출이나 소득 중단에 대비한 현금성 준비금으로 설명합니다. 필요한 액수는 개인 상황에 따라 다르며, 안전하고 접근하기 쉬운 곳에 두도록 권합니다.</p><div class="prompt">예: 꼭 필요한 한 달 생활비를 대략 200만원으로 잡고, 내가 선택한 4개월분인 800만원을 목표로 설정. 매일 지출을 기록할 필요는 없어요. ‘4개월’은 이 예시의 선택이며 기관의 일률적 권고가 아닙니다.</div><p>비상자금은 직접 입력한 현금성 확보액으로 관리해요. 변동성 있는 투자 평가액을 대신 연결하지 않습니다.</p><a href="https://www.consumerfinance.gov/an-essential-guide-to-building-an-emergency-fund/" target="_blank" rel="noopener noreferrer">CFPB · 비상자금 안내 원문 ↗</a></article><article><h3>3. 저축을 미리 정하고, 월 1회 실제 현황 확인</h3><p>CFPB는 구체적 금액의 정기 적립, 자동 이체, 진행 상황 확인을 제안합니다. 앱에서는 이체 조건을 적고 잔액을 점검하는 방식으로 적용했습니다. ‘월 1회’는 기록 부담을 줄이기 위한 이 서비스의 기본 제안입니다.</p><div class="prompt">예: ‘추가 알바비가 들어오면 30%를 비상자금으로 옮긴다.’ 수입 기록만으로 저축 완료 처리하지 않고, 실제 옮긴 뒤 확보액을 업데이트합니다.</div><p class="muted">자동 이체는 본인이 은행에서 설정합니다. 이 앱은 송금하거나 투자 상품을 선택하지 않습니다. 대출 상환 목표는 잔액 감소만 추적하며, 금리·중도상환 조건은 원본에서 확인해주세요.</p></article><article><h3>4. 탈러 · 베나치: 미래의 저축 증액을 미리 정하기</h3><p>Richard Thaler와 Shlomo Benartzi의 Save More Tomorrow(2004)는 직원들이 미래 급여 인상분의 일부를 퇴직저축 증가에 배분하도록 미리 약속하는 접근을 연구했습니다. 이를 참고해 다음 행동에 ‘소득이 늘면 얼마를 더 적립할지’를 적어둘 수 있습니다.</p><div class="prompt">예: ‘다음 급여 인상 때 월 적립액을 10만원 늘릴 수 있는지 점검한다.’ 불규칙한 알바비라면 ‘입금 시 30% 따로 옮기기’처럼 나에게 맞는 규칙을 정해요.</div><p class="muted">직장 퇴직저축 연구를 개인 자금 목표에 응용한 것입니다. 알바 수입 규칙이나 이 앱의 효과가 동일하게 검증됐다는 뜻은 아닙니다.</p><a href="https://doi.org/10.1086/380085" target="_blank" rel="noopener noreferrer">Thaler &amp; Benartzi · Save More Tomorrow ↗</a></article></div></details>`}
function moneyGoalsPanel(){const plan=moneyPlan(),goals=[...plan.goals].sort((a,b)=>Number(a.priority||2)-Number(b.priority||2));return card('돈으로 이루고 싶은 것',`<p class="intro">비상자금 하나부터 시작해도 충분해요. 월 1회 잔액만 점검하세요.</p>${goals.length?`<div class="goal-grid">${goals.map(g=>moneyGoalBox(g)).join('')}</div>`:`<div class="relation-actions">${btn('비상자금부터','money-goal-new',{kind:'reserve'})}${btn('목적자금 모으기','money-goal-new',{kind:'purpose'})}${btn('대출 줄이기','money-goal-new',{kind:'debt'})}</div>`}<p class="muted">목표별 금액은 합산하지 않습니다. 같은 자금을 여러 목표에 연결하면 중복 계획이 될 수 있어요. 투자 평가액은 변동하며 원금 납입과 평가손익을 구분해 원본에서 확인하세요. 월 필요액은 수익률·이자 없이 남은 금액을 남은 개월 수(월 미만 올림)로 나눈 계획값입니다.</p>${moneyMethods()}`,btn('＋ 자금 목표','money-goal-new'))}
document.addEventListener('change',e=>{if(e.target.closest('#moneyGoalForm')&&e.target.name==='selection'){const source=e.target.value.split(':')[0];$('#money-manual-fields').hidden=source!=='manual';$('#money-loan-fields').hidden=source!=='loan';if(source==='loan'&&!e.target.form.elements.baseline.value){const loan=find('loans',e.target.value.slice(5));if(loan)e.target.form.elements.baseline.value=loan.balance;}}});
document.addEventListener('submit',e=>{const f=e.target;if(!['moneyGoalForm','moneyCheckForm'].includes(f.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(f));for(const k in data)data[k]=data[k].trim();const key=f.dataset.id,original=moneyPlan().goals.find(g=>g.id===key),fail=message=>f.querySelector('.error').textContent=message;try{if(f.id==='moneyGoalForm'){const [source,...parts]=data.selection.split(':');delete data.selection;const g={...original,...data,id:key||id(),source,link:parts.join(':')};if(g.kind==='reserve'&&source!=='manual')throw Error('비상자금은 직접 확인한 현금성 확보액으로 설정해주세요.');if(g.kind==='debt'&&source!=='loan')throw Error('상환 목표는 등록한 대출을 연결해주세요.');if(g.kind!=='debt'&&source==='loan')throw Error('대출 연결은 목적을 대출 상환으로 선택해주세요.');HaruMoneyGoals.validate(g,iso());if(source!=='manual'&&!find(source==='loan'?'loans':'investments',g.link))throw Error('연결할 원본 기록을 확인해주세요.');if(updateMoneyPlan(plan=>{const at=plan.goals.findIndex(x=>x.id===g.id);if(at<0)plan.goals.push(g);else plan.goals[at]=g}))closeModal();}else{if(!original)return fail('목표를 찾을 수 없습니다.');const g={...original,current:data.current,asof:data.asof,checkNote:data.note};HaruMoneyGoals.validate(g,iso());if(updateMoneyPlan(plan=>{const at=plan.goals.findIndex(x=>x.id===g.id);moneyCheckpoint(g,db);plan.goals[at]=g}))closeModal();}}catch(error){fail(error.message)}});

function moneyPage(){const principal=sum(db.investments,'principal'),value=sum(db.investments,'value');return heading('ENOUGH TO SEE CLEARLY','내 돈의 목적과 다음 한 걸음','자금 목표를 세우고, 실제 확보액과 투자·대출 현황을 월 1회 확인하세요.')+moneyGoalsPanel()+incomeLedger()+`<div class="notice">직접 입력한 스냅샷입니다. 금융 자동 연동이나 투자 조언을 제공하지 않으며, 모든 자산을 등록한 것이 아니므로 순자산으로 표시하지 않습니다.</div><div class="content-grid"><div>${card('투자 현황',db.investments.length?`<div class="big">${money(value)}</div><p class="muted">등록 투자 평가액 합계 · 기준일은 아래 투자별 확인</p><div class="prompt" style="margin:15px 0">원금 ${money(principal)} · 평가손익 ${money(value-principal)}${principal?' · '+((value-principal)/principal*100).toFixed(1)+'%':''}</div>`+db.investments.map(i=>`<div class="list-card"><div class="goal-top"><h3>${esc(i.name)}</h3>${btn('편집','edit',{table:'investments',id:i.id})}</div><p>${money(i.value)} <small>원금 ${money(i.principal)}</small></p><p class="muted">평가 기준 ${esc(i.date)} · ${esc(i.reason||'투자 이유 미기록')}</p></div>`).join(''):empty('투자명·원금·평가액·기준일만 입력하면 됩니다.'),btn('＋ 투자','edit',{table:'investments'}))}${card('대출 현황',db.loans.length?db.loans.map(l=>`<div class="list-card"><div class="goal-top"><h3>${esc(l.name)}</h3>${btn('편집','edit',{table:'loans',id:l.id})}</div><div class="big">${money(l.balance)}</div><p class="muted">잔액 기준 ${esc(l.asof)}</p>${row('<small>금리 / 상환 방식</small>',`<span>${esc(l.rate)}% · ${esc(l.method)}</span>`)}${row('<small>월 상환 / 다음 납부</small>',`<span>${money(l.monthly)} · ${esc(l.date||'미정')}</span>`)}${row('<small>만기</small>',`<span>${esc(l.maturity||'미정')}</span>`)}</div>`).join(''):empty('잔액·금리·월 상환액·만기를 한곳에서 확인하세요.'),btn('＋ 대출','edit',{table:'loans'}))}</div><div>${card('입력 주기','<p style="font-size:12px">투자 현황은 월 1회 또는 거래 시.<br>대출은 조건이나 잔액 변화 시.<br><br>일일 지출 기록은 필요 없습니다. 추가 알바 수입은 위에서 월별로 확인하고, 원할 때 입금 여부를 기록합니다.</p>')}</div></div>`}


function weeklySignals(period){const end=addDays(period,6),health=db.health.filter(h=>h.date>=period&&h.date<=end),logs=db.timeLogs.filter(t=>t.date>=period&&t.date<=end),diaries=db.reviews.filter(r=>r.kind==='일간'&&r.period>=period&&r.period<=end&&r.result.trim()),exercise=health.filter(h=>h.exercise),drink=health.filter(h=>h.drink),minutes=sum(logs,'minutes');const roles=[...new Set(logs.map(l=>l.role))];return card('이번 주 흐름',`<p class="muted">${esc(period)} ~ ${end} · 입력한 기록만 집계합니다.</p><div class="metric-grid" style="margin-top:15px"><div class="metric"><small>일기 작성</small><strong>${diaries.length}일</strong><small>이 주의 7일 중</small></div><div class="metric"><small>운동한 날</small><strong>${exercise.filter(h=>h.exercise==='운동함').length}일</strong><small>${exercise.length}일 여부 기록</small></div><div class="metric"><small>술 마신 날</small><strong>${drink.filter(h=>h.drink==='마심').length}일</strong><small>${drink.length}일 여부 기록</small></div><div class="metric"><small>시간 기록 합계</small><strong>${(minutes/60).toLocaleString('ko-KR',{maximumFractionDigits:1})}h</strong><small>${logs.length}개 구간 · 전체 시간 아님</small></div></div><details class="diary-extra"><summary>시간 배분 · 관계 · 수면 더 보기</summary>${roles.map(role=>{const n=sum(logs.filter(l=>l.role===role),'minutes');return `<div class="list-card"><div class="goal-top"><small>${esc(byName('roles',role,'미지정'))}</small><small>${(n/60).toLocaleString('ko-KR',{maximumFractionDigits:1})}h</small></div><div class="progress"><i style="width:${minutes?n/minutes*100:0}%"></i></div></div>`}).join('')||'<p class="muted">기록한 시간 구간이 없어요.</p>'}<p class="muted" style="margin-top:12px">막대는 기록한 시간 합계 안에서의 비중입니다. 미기록 시간을 낭비로 판단하지 않습니다.</p><div class="row"><small>함께한 시간</small><b>${(sum(db.moments.filter(m=>m.date>=period&&m.date<=end),'minutes')/60).toLocaleString('ko-KR',{maximumFractionDigits:1})}h</b></div><div class="row"><small>평균 수면</small><b>${health.filter(h=>h.sleep!=='').length?(sum(health.filter(h=>h.sleep!==''),'sleep')/health.filter(h=>h.sleep!=='').length).toFixed(1)+'h':'미입력'}</b></div><p class="muted">수면 평균은 시간을 기록한 날만 기준으로 합니다. 관계 시간과 시간 기록은 겹칠 수 있어 서로 합산하지 않습니다.</p></details><p class="muted">기록 횟수는 건강이나 삶의 성적표가 아닙니다. 다음 주 바꿀 것 하나를 찾는 단서로 봐주세요.</p>`);}

function weeklyDiaryInsights(period){const entries=db.reviews.filter(r=>r.kind==='일간'&&r.period>=period&&r.period<=addDays(period,6)&&r.result.trim()).sort((a,b)=>a.period.localeCompare(b.period));return card('이번 주 일기에서 발견한 것',entries.length?entries.map(r=>`<article class="list-card"><div class="goal-top"><b>${esc(r.period)}</b>${btn('일기 열기','review-open',{id:r.id})}</div><p class="review-excerpt" style="margin-top:9px">${esc(r.result)}</p>${r.learning?`<div class="prompt" style="margin-top:10px">발견한 점<br>${esc(r.learning)}</div>`:''}${r.experiment?`<div class="next-action"><b>다음 시도</b><br>${esc(r.experiment)}</div>${reviewAction(r)}`:''}</article>`).join(''):'<p class="empty">이 주에 남긴 일기가 모입니다. 일기에 적은 발견과 다음 시도를 보며 주간 점검을 작성해보세요.</p>');}
function healthRhythm(){const days=Array.from({length:7},(_,i)=>addDays(today,i-6));return card('생활 리듬 · 최근 7일',`<p class="muted">음주·운동은 건강에 함께 기록해요. 미입력은 ‘안 함’과 다릅니다.</p><div class="health-rhythm"><div class="rhythm-row rhythm-head"><span>날짜</span><span>운동</span><span>음주</span><span>기록</span></div>${days.map(day=>{const h=db.health.find(h=>h.date===day);return `<div class="rhythm-row"><small>${day.slice(5)}</small><span class="${h?.exercise==='운동함'?'positive':''}">${esc(h?.exercise||'미입력')}</span><span>${esc(h?.drink||'미입력')}</span>${btn('편집','health-date',{date:day},'linkbutton')}</div>`}).join('')}</div><div class="prompt" style="margin-top:15px">횟수는 상태를 알아보기 위한 단서입니다. 연속 기록이나 완벽한 달성률을 요구하지 않아요.</div>`);}

function healthPage(){return heading('CARE WITHOUT PRESSURE','몸과 마음의 흐름','CEO Diary의 건강 항목을 바탕으로. 한 항목만 남겨도 충분합니다.',btn('＋ 건강 기록','edit',{table:'health'},'outline'))+`<div class="content-grid"><div>${card('최근 상태',healthStats())}${healthRhythm()}${card('날짜별 기록',db.health.length?[...db.health].sort((a,b)=>b.date.localeCompare(a.date)).map(h=>`<div class="list-card"><div class="goal-top"><h3>${esc(h.date)}</h3>${btn('편집','edit',{table:'health',id:h.id})}</div><p style="font-size:12px">${[h.sleep!==''?'수면 '+h.sleep+'h':'',h.weight?'체중 '+h.weight+'kg':'',h.minutes!==''?'활동 '+h.minutes+'분':'',h.exercise,h.mood,h.drink].filter(Boolean).map(esc).join(' · ')}</p><p class="muted">${esc(h.memo||'')}</p></div>`).join(''):empty('매일 채울 필요는 없어요. 기록하지 않은 날은 ‘안 함’과 구분합니다.'))}</div><div>${card('건강과 연결된 목표',db.goals.filter(g=>g.role==='self').map(goalBox).join('')||empty('나 자신 역할에 건강 목표를 연결해보세요.',btn('목표 추가','new-goal',{role:'self'},'outline')))}${card('나를 돌보는 기록','<p style="font-size:12px">수면 · 체중 · 활동 · 기분 · 음주를 선택 입력합니다. 식단·통증·몸의 변화는 필요할 때 메모로.<br><br>체중은 건강 전체를 대표하지 않습니다. 이 서비스는 의료 진단이나 건강 점수를 제공하지 않습니다.</p>')}</div></div>`}
function relationshipHome(){const day=iso(),events=HaruRelationships.upcoming(db.people,day,30).slice(0,3),picks=HaruRelationships.picks(db.people,db.moments,day),due=db.people.filter(p=>HaruRelationships.followUp(p,db.moments,day).show);return card('관계 · 안부',events.map(e=>row(esc(e.name)+' · '+esc(e.title),esc(e.date.slice(5)))).join('')+row('오늘 연락하고 싶은 사람',`${picks.filter(p=>!p.done).length}명`)+`<p class="muted">${picks.filter(p=>!p.done).slice(0,3).map(({person:p})=>esc(p.name)).join(' · ')}</p>`+row('안부를 떠올려볼 사람',`${due.length}명`)+`<p class="muted">앱을 열 때 확인해요. 자동 메시지·알림은 보내지 않습니다.</p>`,btn('관계 보기 ↗','go',{page:'relations'}))}
function relationPersonForm(key){const p=find('people',key)||{};modal('중요한 사람',`<p class="intro">이름만으로 시작해도 좋아요. 생일과 안부 주기는 선택입니다.</p><form id="relationPersonForm" data-id="${esc(key||'')}">${field(def('name','이름·별칭','text',{required:true,max:80}),p)}${field(def('group','관계','select',{options:['가족','친구','동료','기타']}),p)}${field(def('note','기억할 것·함께 하고 싶은 것','textarea'),p)}<details ${p.birthday||p.contactEveryDays?'open':''}><summary>생일 · 안부 주기 (선택)</summary>${field(def('birthday','생일 월-일 (예: 02-29)','text',{placeholder:'MM-DD'}),p)}${field(def('birthdayBasis','생일 기준','select',{options:[['solar','양력'],['lunar','음력']]}),p)}${field(def('birthdaySolarDate','음력 생일: 확인한 양력 날짜','date'),p)}<p class="muted">음력은 자동 변환하지 않습니다. 매년 확인한 양력 날짜를 새로 입력해주세요.</p>${field(def('leapPolicy','2월 29일이 없는 해','select',{options:[['feb28','2월 28일에 챙기기'],['mar1','3월 1일에 챙기기'],['leap-only','윤년에만 표시']]}),p)}${field(def('contactEveryDays','안부 주기 (일, 비우면 사용 안 함)','number',{min:1,max:3650,step:1}),p)}${field(def('lastContact','최근 연락일 (알고 있는 경우만)','date',{max:iso()}),p)}<label class="check"><input type="checkbox" name="contactPaused" ${p.contactPaused?'checked':''}>정기 안부 제안 잠시 쉬기</label></details><p class="error" role="alert"></p><div class="form-actions">${key?btn('삭제','delete',{table:'people',id:key},'delete'):''}${btn('취소','close')}<button class="primary">저장</button></div></form>`)}
function relationActionForm(action,key){const p=find('people',key);if(!p){toast('먼저 중요한 사람을 추가해주세요.');return}let title='',body='';if(action==='anniversary'){title='기념일 추가';body=field(def('title','기념일 이름','text',{required:true,max:120}),{})+field(def('date','처음 챙길 날짜','date',{required:true}),{})+field(def('repeat','반복','select',{options:[['yearly','매년'],['once','이번 한 번']]}),{})+field(def('leapPolicy','2월 29일이 없는 해','select',{options:[['feb28','2월 28일'],['mar1','3월 1일'],['leap-only','윤년에만']]}),{})}else if(action==='contact'){title='실제로 안부를 나눴나요?';body='<p class="intro">직접 연락한 뒤 기록해주세요. 이 버튼은 메시지를 보내지 않습니다.</p>'+field(def('date','연락한 날짜','date',{required:true,value:iso(),max:iso()}),{})+field(def('contactChannel','연락 방법','select',{options:['전화','메시지','만남','기타']}),{})+field(def('note','기억할 것 (선택)','textarea'),{})}else if(action==='snooze'){title='다음에 안부 떠올리기';body=field(def('snoozeUntil','다시 떠올릴 날짜','date',{required:true,min:iso(),value:addDays(iso(),7)}),{})}else{title='오늘 연락하고 싶은 사람';body=field(def('reachOutNote','떠오른 이유 · 나누고 싶은 말 (선택)','textarea'),p)+'<p class="muted">계획만 남깁니다. 실제 연락일은 바뀌지 않아요.</p>'}modal(title,`<p class="intro">${esc(p.name)}</p><form id="relationActionForm" data-id="${esc(key)}" data-kind="${action}">${body}<p class="error" role="alert"></p><div class="form-actions">${btn('취소','close')}<button class="primary">${action==='contact'?'연락한 사실 저장':'저장'}</button></div></form>`)}
function saveRelationshipForm(e){const f=e.target;if(!['relationPersonForm','relationActionForm'].includes(f.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(f));for(const k in data)data[k]=data[k].trim();const key=f.dataset.id,original=find('people',key),day=iso();const fail=msg=>{f.querySelector('.error').textContent=msg};if(f.id==='relationPersonForm'){if(!data.name)return fail('이름이나 별칭을 입력해주세요.');if(data.birthday){const parts=/^(\d{2})-(\d{2})$/.exec(data.birthday);if(!parts)return fail('생일을 MM-DD 형식으로 입력해주세요.');if(data.birthdayBasis==='lunar'?(+parts[1]<1||+parts[1]>12||+parts[2]<1||+parts[2]>30):!HaruRelationships.annual(data.birthday,day))return fail('생일의 월과 일을 확인해주세요.')}if(data.lastContact&&(!HaruRelationships.date(data.lastContact)||data.lastContact>day))return fail('최근 연락일은 오늘까지의 날짜로 입력해주세요.');if(data.contactEveryDays&&(!/^\d+$/.test(data.contactEveryDays)||+data.contactEveryDays<1||+data.contactEveryDays>3650))return fail('안부 주기는 1~3650일로 입력해주세요.');data.contactPaused=new FormData(f).has('contactPaused');const item={...original,...data,id:key||id(),followupSince:original?.followupSince||day};if(commit(n=>{const at=n.people.findIndex(p=>p.id===item.id);if(at<0)n.people.push(item);else n.people[at]=item}))closeModal();return}if(!original)return fail('사람을 찾을 수 없습니다.');const action=f.dataset.kind;if(action==='contact'&&(!HaruRelationships.date(data.date)||data.date>day))return fail('실제 연락한 날짜는 오늘까지 입력해주세요.');if(action==='anniversary'&&(!data.title||!HaruRelationships.date(data.date)))return fail('기념일 이름과 날짜를 확인해주세요.');if(action==='snooze'&&(!HaruRelationships.date(data.snoozeUntil)||data.snoozeUntil<day))return fail('오늘 이후 날짜를 입력해주세요.');if(commit(n=>{const p=n.people.find(p=>p.id===key);if(action==='contact'){n.moments.push({id:id(),person:key,title:data.contactChannel+'로 안부',date:data.date,minutes:'',note:data.note,kind:'contact',contactChannel:data.contactChannel})}else if(action==='anniversary'){const events=HaruRelationships.anniversaries(p);events.push({id:id(),...data});p.anniversaries=JSON.stringify(events)}else if(action==='snooze')p.snoozeUntil=data.snoozeUntil;else{p.reachOutDate=day;p.reachOutStatus='planned';p.reachOutNote=data.reachOutNote}}))closeModal()}
document.addEventListener('submit',saveRelationshipForm);
function relationsPage(){const day=iso(),events=HaruRelationships.upcoming(db.people,day,30),picks=HaruRelationships.picks(db.people,db.moments,day),due=db.people.filter(p=>HaruRelationships.followUp(p,db.moments,day).show);return heading('PEOPLE, NOT SCORES','소중한 사람들과 함께','중요한 사람 한 명부터. 생일과 안부 주기는 필요할 때만 추가하세요.',btn('＋ 사람 추가','edit',{table:'people'},'outline'))+`<div class="two">${card('오늘 연락하고 싶은 사람',picks.length?picks.map(({person:p,done})=>`<div class="list-card"><h3>${esc(p.name)} ${done?tag('연락 기록 있음'):''}</h3><p>${esc(p.reachOutNote||'그냥 생각나서')}</p>${!done?btn('실제로 연락했어요','relation-contact',{id:p.id})+btn('오늘은 넘기기','relation-dismiss',{id:p.id}):''}</div>`).join(''):empty('생각나는 사람의 ‘오늘 떠올리기’를 눌러보세요. 계획만으로 연락일이 바뀌지 않아요.'))}${card('다가오는 생일 · 기념일',events.length?events.map(e=>row(`<b>${esc(e.name)}</b> · ${esc(e.title)} ${e.basis==='직접 확인한 양력일'?'(확인한 양력일)':''}`,`${esc(e.date)} · ${e.offset===0?'오늘':e.offset+'일 뒤'}`)).join(''):empty('앞으로 30일 안에 등록된 기념일이 없어요.'))}</div>${card('안부를 떠올려볼 사람',due.length?due.map(p=>{const status=HaruRelationships.followUp(p,db.moments,day);return row(`<b>${esc(p.name)}</b><p class="muted">${status.last?'최근 연락 '+esc(status.last):'연락 기록 없이 설정한 주기 기준'} · ${esc(p.contactEveryDays)}일 주기</p>`,btn('오늘 떠올리기','relation-pick',{id:p.id})+btn('다음에','relation-snooze',{id:p.id}))}).join(''):empty('지금 표시할 정기 안부 제안이 없어요. 사람별 편집에서 주기를 설정할 수 있습니다.'))}<div class="content-grid"><div>${card('나의 관계',db.people.length?db.people.map(p=>{const last=HaruRelationships.lastContact(p,db.moments,day),ann=HaruRelationships.anniversaries(p);return `<div class="list-card"><div class="goal-top"><h3>${esc(p.name)} ${tag(p.group)}</h3>${btn('편집','edit',{table:'people',id:p.id})}</div><p>${esc(p.note)}</p><p class="muted">최근 연락 · ${esc(last||'아직 기록 없음')}${p.contactEveryDays?' / '+esc(p.contactEveryDays)+'일 주기':''}${p.contactPaused?' · 제안 쉬는 중':''}${p.snoozeUntil>day?' · '+esc(p.snoozeUntil)+'까지 미룸':''}</p>${p.birthday?`<p class="muted">생일 · ${esc(p.birthday)} (${p.birthdayBasis==='lunar'?'음력':'양력'})</p>`:''}${p.birthdayBasis==='lunar'&&(!p.birthdaySolarDate||p.birthdaySolarDate<day)?'<p class="due">다음 음력 생일의 양력 날짜를 확인해주세요.</p>':''}${ann.map(a=>row(`${esc(a.title)} · ${esc(a.date)} · ${a.repeat==='yearly'?'매년':'한 번'}`,btn('삭제','relation-ann-delete',{id:p.id,event:a.id}))).join('')}<div class="relation-actions">${btn('오늘 떠올리기','relation-pick',{id:p.id})}${btn('연락 기록','relation-contact',{id:p.id})}${btn('기념일 ＋','relation-anniversary',{id:p.id})}${btn('함께한 순간 ＋','new-moment',{person:p.id})}</div></div>`}).join(''):empty('별칭으로 등록해도 괜찮아요.'))}${card('함께한 순간 · 연락 기록',db.moments.length?[...db.moments].sort((a,b)=>b.date.localeCompare(a.date)).map(m=>`<article class="note"><div class="goal-top"><b>${esc(m.title)} ${m.kind==='contact'?tag('실제 연락'):''}</b>${btn('편집','edit',{table:'moments',id:m.id})}</div><p>${esc(m.note)}</p><span class="muted">${esc(byName('people',m.person,'관계 미지정'))} · ${esc(m.date)}${m.minutes?' · '+esc(m.minutes)+'분':''}</span></article>`).join(''):empty('식사, 전화, 산책처럼 기억하고 싶은 순간을 남겨요.'),btn('＋ 순간','edit',{table:'moments'}))}</div><div>${card('챙길 일과 필요한 대화',db.issues.length?db.issues.map(i=>`<div class="list-card"><label class="check"><input type="checkbox" data-toggle="issues" data-id="${esc(i.id)}" ${i.done?'checked':''}><span>${esc(i.title)}</span></label><p class="muted">${esc(byName('people',i.person,'관계 미지정'))} · ${esc(i.date||'날짜 미정')}</p><div class="next-action">${esc(i.next)}</div>${btn('편집','edit',{table:'issues',id:i.id})}</div>`).join(''):empty('가족 관련 이슈나 나누고 싶은 대화를 남겨요.'),btn('＋ 이슈','edit',{table:'issues'}))}${card('기록한 함께한 시간',row('이번 달',`${(sum(db.moments.filter(m=>m.date.startsWith(day.slice(0,7))&&m.date<=day),'minutes')/60).toLocaleString('ko-KR',{maximumFractionDigits:1})}시간`)+row('열린 관계 이슈',`${db.issues.filter(i=>!i.done).length}건`)+'<p class="muted">시간을 입력한 순간만 집계합니다. 관계의 질을 나타내는 수치는 아니에요.</p>')}${card('내 속도에 맞게','<p>주기는 연락을 강요하는 기준이 아닌, 사람을 떠올리는 보조 장치예요. 쉬거나 미뤄도 됩니다.</p><p class="muted">실제 연락일은 확인한 연락 기록에서 계산합니다. 기록을 삭제하면 다시 계산해요. 알림은 앱 안에서만 표시되며 자동 메시지는 보내지 않습니다. 사람별 점수나 순위를 매기지 않아요.</p>','', 'summary-green')}</div></div>`}

function reviewTabs(){return ['일간','주간','분기','연간'].map(k=>btn(k==='일간'?'오늘 하루':k+' 점검','review-kind',{kind:k},'chip '+(reviewKind===k?'on':''))).join('');}
function dailyHomeCard(){const entry=db.reviews.find(r=>r.kind==='일간'&&r.period===today);const days=Array.from({length:7},(_,i)=>addDays(today,i-6));const count=days.filter(d=>db.reviews.some(r=>r.kind==='일간'&&r.period===d&&r.result.trim())).length;return card('오늘 하루, 나에게 남기는 한 줄',`<div class="daily-home"><div><span class="tone">${entry?.result?'오늘 일기 저장됨 ✓':'아직 쓰지 않았어요'}</span><p class="review-excerpt" style="margin:12px 0">${esc(entry?.result||'오늘 기억하고 싶은 순간이 있나요? 잘 쓴 글보다 나의 말 한 줄이면 충분해요.')}</p>${btn(entry?'오늘 일기 이어쓰기 ↗':'오늘 일기 쓰기 ＋','daily-open',{date:today},'linkbutton')}</div><div><span class="muted">최근 7일 중 ${count}일 기록</span><div class="diary-days">${days.map(d=>{const written=db.reviews.some(r=>r.kind==='일간'&&r.period===d&&r.result.trim());return `<button type="button" data-action="daily-open" data-date="${d}" class="diary-day ${written?'written':''} ${d===today?'today':''}" aria-label="${d} 일기 ${written?'작성됨':'미작성'}"><small>${['일','월','화','수','목','금','토'][new Date(d+'T12:00:00+09:00').getUTCDay()]}</small><b>${Number(d.slice(8))}</b><span>${written?'•':'·'}</span></button>`}).join('')}</div><p class="muted">쉬어간 날이 있어도 다시 쓰면 돼요.</p></div></div>`,btn('지난 일기 ↗','daily-open',{date:today}));}
function dailyReviewPage(){const r=db.reviews.find(x=>x.kind==='일간'&&x.period===reviewPeriod),entries=db.reviews.filter(r=>r.kind==='일간'&&r.result.trim()).sort((a,b)=>b.period.localeCompare(a.period));const notes=db.notes.filter(n=>n.date===reviewPeriod);return heading('A MOMENT FOR YOURSELF','오늘 하루','성과가 없어도 괜찮아요. 하루를 살아낸 나에게 이야기를 남겨주세요.')+`<div class="toolbar">${reviewTabs()}</div><div class="content-grid"><div>${card('하루 일기',`<form id="dailyDateForm" class="diary-date"><label for="diary-date">기록 날짜</label><input id="diary-date" type="date" name="day" value="${esc(reviewPeriod)}" max="${today}" required><button class="outline">날짜 열기</button>${reviewPeriod!==today?btn('오늘로','daily-open',{date:today}):''}</form><p class="muted">${r?.result?'저장된 일기입니다. 같은 날짜에 다시 저장하면 내용을 수정합니다.':'새 일기입니다. 한 줄만 써도 저장할 수 있어요.'}</p><form id="reviewForm">${field(def('result','1. 오늘 마음에 남은 장면과 감정은?','textarea',{required:true,max:12000,placeholder:'어떤 일이 있었나요? 그때 어떤 마음이 들었나요? 장면 하나면 충분해요.'}),r||{})}${field(def('learning','2. 왜 그랬을까? 무엇을 알게 됐나요? · 선택','textarea',{placeholder:'잘된 조건, 어려웠던 이유, 나에 대해 새로 알게 된 것. 교훈을 억지로 찾지 않아도 돼요.'}),r||{})}${field(def('experiment','3. 비슷한 상황이 오면 무엇을 해볼까요? · 선택','textarea',{placeholder:'예: 화요일 저녁이 되면, PWR 작업 45분을 먼저 확보한다.'}),r||{})}<details class="diary-extra" ${r?.next||r?.obstacle||r?.stop?'open':''}><summary>감사 기록 · 마음에 걸리는 날 · 선택</summary>${field(def('obstacle','오늘의 마음 · 어려웠던 것','textarea'),r||{})}${field(def('stop','고마웠던 순간 · 기억하고 싶은 것','textarea'),r||{})}${field(def('next','내일의 나에게 한마디','textarea'),r||{})}<p class="muted">마음에 걸리는 날에는 사실과 해석을 구분해볼 수 있어요. 아래는 CBT 생각 기록을 참고한 간단 질문이며 치료 도구 전체를 재현한 것은 아닙니다.</p>${field(def('facts','확인할 수 있는 사실은?','textarea'),r||{})}${field(def('interpretation','나는 그 일을 어떻게 해석했나요?','textarea'),r||{})}${field(def('alternative','다른 설명이나 더 균형 잡힌 관점은?','textarea'),r||{})}</details><p class="error" id="dailyError" role="alert"></p><div class="form-actions"><span class="muted">저장 버튼을 누르면 날짜별로 보관됩니다.</span><button class="primary">${r?'일기 수정 저장':'오늘 일기 저장'}</button></div></form>`)}${card('그날 남긴 짧은 기록',notes.length?notes.map(n=>`<article class="note"><p>${esc(n.text)}</p></article>`).join(''):empty('그날의 한 줄 기록이 있으면 이곳에서 함께 볼 수 있어요.'))}</div><div>${card('지난 나의 하루',entries.length?entries.slice(0,14).map(e=>`<article class="list-card"><div class="goal-top"><b>${esc(e.period)}</b>${btn('다시 읽기','daily-open',{date:e.period})}</div><p class="review-excerpt" style="margin-top:9px">${esc(e.result)}</p></article>`).join('')+(entries.length>14?'<p class="muted" style="margin-top:12px">최근 14일기만 표시됩니다. 더 오래된 일기는 날짜를 선택하거나 지난 점검 목록에서 열 수 있어요.</p>':''):empty('첫 일기를 쓰면 날짜별로 쌓여요.'))}${card('경험을 이해하는 3분 일기','<p style="font-size:12px">깁스의 성찰 순환에서 경험·감정·분석·배움·행동의 흐름을 짧게 응용했습니다. 이 3문항 조합 자체의 효과가 검증됐다는 뜻은 아닙니다.<br><br>장면 한 줄만 남겨도 괜찮아요. 원인과 다음 행동은 생각나는 날에만 적어요.</p>',btn('방법과 출처 ↗','guide'))}${card('습관은 작게 시작하기','<p style="font-size:12px">예를 들어 “잠들기 전 충전기를 꽂으면, 일기를 한 줄 쓴다”처럼 이미 하는 행동에 연결해보세요.<br><br>쓸 말이 없는 날에는 “오늘은 조금 피곤했다”도 충분합니다. 연속 기록이 끊겨도 실패가 아니에요.</p>','', 'summary-green')}</div></div>`;}

function reviewPage(){if(reviewKind==='일간')return dailyReviewPage();const r=db.reviews.find(x=>x.kind===reviewKind&&x.period===reviewPeriod),logs=db.timeLogs.filter(l=>l.date>=week&&l.date<=today),questions=reviewKind==='주간'?[['result','이번 주, 실제로 앞으로 나아간 것은?'],['obstacle','무엇이 나를 막았나요?'],['next','다음 주, 급하지 않아도 중요한 한 가지는?'],['stop','일·가족·건강·휴식을 위해 무엇을 줄이거나 미룰까요?']]:reviewKind==='분기'?[['result','목표별로 어떤 성과와 변화가 있었나요?'],['obstacle','지금도 내게 중요한 목표인가요? 막히는 것은?'],['next','다음 분기에 집중할 것 하나는?'],['stop','그만두거나 조정할 일은?']]:[['result','올해 의미 있었던 성과와 관계는?'],['obstacle','예상과 달랐던 결과, 배운 것은?'],['next','다음 해의 방향과 가장 중요한 역할은?'],['stop','지키고 싶은 원칙과 내려놓을 것은?']];return heading('REFLECT, THEN RECOMMIT','돌아보고, 방향을 고르기','나를 채점하는 시간이 아니라, 다음 선택을 더 잘하기 위한 시간.')+`<div class="toolbar">${reviewTabs()}</div><div class="content-grid"><div>${card(`${reviewKind} 점검 · ${esc(reviewPeriod)}`,`<p class="muted">${reviewKind==='주간'?'현재 주의 월요일 기준':'선택한 기간 기준'} · 과거 기록은 아래에서 다시 열 수 있어요.</p>${reviewKind==='주간'?previousReviewContext(reviewPeriod):''}<form id="reviewForm">${questions.map(([k,q])=>field({name:k,label:q,type:'textarea'},r||{})).join('')}<div class="form-actions"><button class="primary">점검 저장</button></div></form>`)}${card('중요한 결정 · 피드백 분석',db.decisions.length?[...db.decisions].sort((a,b)=>b.created.localeCompare(a.created)).map(d=>`<article class="list-card"><div class="goal-top"><h3>${esc(d.title)}</h3>${btn('결과·강점 기록','edit',{table:'decisions',id:d.id})}</div><p class="muted">결정일 ${esc(d.created)} · 확인할 날짜 ${esc(d.date)}</p><div class="prompt" style="margin-top:12px">예상 결과<br>${esc(d.expected)}</div><p style="font-size:12px;margin-top:10px">실제 결과 · ${esc(d.actual||'점검하는 날 적어요.')}</p>${d.strength?`<p class="muted">발견한 강점 · ${esc(d.strength)}</p>`:''}</article>`).join(''):empty('중요한 결정이나 시도 전에 예상 결과를 적어두세요.<br>드러커는 9~12개월 뒤 실제 결과와 비교할 것을 제안했습니다. 점검일은 상황에 맞게 바꿀 수 있습니다.'),btn('＋ 결정 노트','edit',{table:'decisions'}))}${reviewKind==='주간'?weeklyDiaryInsights(reviewPeriod):''}${card('지난 점검',db.reviews.length?[...db.reviews].sort((a,b)=>b.period.localeCompare(a.period)).map(r=>row(`${tag(r.kind)} ${esc(r.period)}`,btn('다시 열기','review-open',{id:r.id}))).join(''):empty('매일 일기와 주간·분기·연간 점검을 기간별로 보관합니다.'))}</div><div>${reviewKind==='주간'?weeklySignals(reviewPeriod):''}${card('기록에서 발견한 나의 강점',`<p style="white-space:pre-wrap;font-size:12px">${esc(db.profile.strengths||'어떤 조건에서 성과를 냈나요? 실제 결과와 경험에서 찾은 강점을 적어보세요.')}</p>`,btn('정리하기','vision'))}${card('이번 주 시간 기록',logs.length?`<div class="big">${(sum(logs,'minutes')/60).toFixed(1)} <small>시간</small></div><p class="muted">기록한 구간 합계 · 하루 전체를 대표하지 않아요.</p>`+logs.map(l=>row(`<span>${esc(l.title)}</span><p>${esc(byName('roles',l.role,'개인'))} · ${l.minutes}분</p>`,btn('편집','edit',{table:'timeLogs',id:l.id}))).join(''):empty('시간을 어떻게 썼는지 짧게 관찰해보세요. 오래 걸린 일이나 중요한 일만 남겨도 됩니다.'),btn('＋ 시간 기록','edit',{table:'timeLogs'}))}${card('주기는 제품의 제안','<p style="font-size:12px">역할별 주간 계획은 코비의 접근을 참고했습니다. 분기·연간 점검의 화면과 질문은 이 서비스의 응용이며 특정 저자의 원문 체크리스트가 아닙니다.</p>',btn('근거와 적용 ↗','guide'))}</div></div>`}
function guidePage(){const source=(title,label,summary,applied,href,ref)=>`<article class="source"><span class="tone">${label}</span><h3 style="margin-top:12px">${title}</h3><p>${summary}</p><blockquote>이 서비스에 적용 · ${applied}</blockquote>${href?`<a href="${href}" target="_blank" rel="noopener noreferrer">${ref} ↗</a>`:`<small>${ref}</small>`}</article>`;return heading('BUILT ON METHODS, NOT QUOTES','왜 이렇게 구성했나요?','좋은 문구를 붙이기보다, 검토하고 실행할 수 있는 도구로.')+`<div class="reading">${card('핵심 설계 원칙','<div class="stack"><p><b>드러커:</b> 나의 강점·시간·기여를 알고, 예상과 실제 결과를 비교합니다.</p><p><b>코비:</b> 삶의 역할을 놓치지 않고, 중요한 일을 주간 계획에 먼저 배치합니다.</p><p><b>행동 연구:</b> 원하는 결과와 장애물을 보고, 시작 조건과 작은 행동을 구체화합니다.</p></div>')}<div class="notice">‘자기관리 전문가’는 하나의 공인 자격이 아닙니다. 아래는 출판된 저술과 연구에 기반한 방법이며, 저자마다 근거의 성격이 다릅니다. 이 서비스나 모든 기법의 조합이 검증되었다는 뜻은 아닙니다. 현재 네트워크 제한으로 원문 본문을 실시간 재확인하지 못했으므로 최신 문헌 검토를 주장하지 않습니다.</div>${card('방법과 도구',source('그레이엄 깁스 · 성찰 순환','성찰 교육 모형','경험, 감정, 평가, 분석, 결론, 행동 계획을 돌아보는 모형입니다. 이 축약 일기의 효과 자체가 검증됐다는 의미는 아닙니다.','장면과 감정 → 발견한 점 → 다음 시도의 3문항으로 축약했습니다. 한 줄 기록만 필수이며 나머지는 선택입니다.','','Graham Gibbs, Learning by Doing (1988)')+source('CBT의 생각 기록','치료에서 활용하는 도구','상황·생각·감정을 구분하고 근거와 대안적 관점을 검토합니다. 이 서비스의 간단 질문은 정식 생각 기록 전체나 치료를 대신하지 않습니다.','마음에 걸리는 날에만 사실·해석·다른 설명을 적을 수 있도록 선택 항목을 두었습니다.','https://www.nhs.uk/mental-health/self-help/guides-tools-and-activities/thought-record/','NHS Thought record')+source('감사 기록 · 에먼스와 매컬러','긍정심리학 연구','감사할 경험에 주목하는 기록을 연구한 저술입니다. 효과는 측정 항목과 맥락에 따라 다르며 모든 사람에게 같은 효과를 보장하지 않습니다.','원할 때 고마웠던 순간 하나를 남깁니다. 힘든 감정을 지우거나 긍정적으로 해석하도록 강요하지 않습니다.','https://doi.org/10.1037/0022-3514.84.2.377','Emmons & McCullough (2003), Counting Blessings Versus Burdens')+source('피터 드러커 · 피드백 분석','경영 저술','중요한 결정과 행동 시 기대 결과를 기록하고 9~12개월 후 실제 결과와 비교하여 강점과 성과를 내는 방식을 파악하는 접근입니다.','결정일 → 예상 결과 → 확인할 날짜 → 실제 결과 → 발견한 강점. 기본 점검일은 9개월 후이며 사용자가 바꿀 수 있습니다.','https://hbr.org/2005/01/managing-oneself','Managing Oneself (1999; HBR 재수록 2005)')+source('피터 드러커 · 시간과 기여','경영 저술','《The Effective Executive》는 실제 시간 사용을 파악하고, 자신의 활동보다 기여와 성과에 초점을 두는 접근을 설명합니다.','실제 사용 시간 기록과 역할별 목적·목표. 이 서비스의 선택적 간단 기록은 원 저술의 체계적인 시간 기록을 축약한 응용입니다.','','The Effective Executive (1967), Know Thy Time / What Can I Contribute?')+source('스티븐 코비 · 역할과 중요한 일','자기관리 저술','역할별 목표를 정하고 중요하지만 긴급하지 않은 일을 주간 계획에 배치하는 접근입니다.','본업·사이드프로젝트·가족·나 자신을 한 화면에. 역할별 목표와 이번 주 한 걸음을 연결합니다.','','The 7 Habits of Highly Effective People (1989), 습관 2·3')+source('가브리엘레 외팅겐 · WOOP','심리학 연구 기반','Wish·Outcome·Obstacle·Plan: 원하는 미래와 이를 가로막는 장애물을 함께 보고 계획을 세우는 방법입니다.','목표의 이유·바라는 결과·내적 장애물·실행 계획. 단순한 목표 목록을 준비와 행동으로 연결합니다.','https://woopmylife.org/en/practice','WOOP 공식 실천 안내')+source('피터 골비처 · 실행 의도','심리학 연구','특정 상황과 행동을 if–then 형식으로 연결하는 계획입니다. 효과는 목표와 상황에 따라 달라질 수 있습니다.','“일요일 저녁 식사 후라면, 여행 예산을 10분 정리한다”처럼 실행 조건을 적습니다.','https://doi.org/10.1037/0003-066X.54.7.493','Gollwitzer (1999), Implementation Intentions')+source('BJ 포그 · 행동 모형','행동 설계 모형','행동이 일어나려면 동기·실행 용이성·촉발 신호가 함께 작용한다는 모형입니다.','일을 더 작게 나누고, 시작 신호를 정하도록 안내합니다. 자동으로 습관 형성 효과를 보장하지 않습니다.','https://www.behaviormodel.org/','Fogg Behavior Model')+source('에드워드 데시·리처드 라이언 · 자기결정성이론','심리학 이론','자율성·유능감·관계성을 주요 심리적 욕구로 다룹니다. 이는 가족과 보낸 시간을 점수화하라는 의미가 아닙니다.','자신이 원하는 이유를 먼저 쓰고, 관계에는 시간과 순간을 기록하되 타인을 평가하는 점수는 두지 않습니다.','https://selfdeterminationtheory.org/theory/','Self-Determination Theory 공식 설명'))}${card('이번 버전의 범위','<p style="font-size:12px">기록·목표·역할·할 일·건강·관계·투자·대출·점검을 직접 입력하고 본인 계정의 서버에 저장합니다. Supabase 로그인과 계정별 서버 저장을 사용합니다. Google Calendar는 읽기 전용으로 선택 연결할 수 있습니다. 원본 일정과 실제 시간은 구분하며, 금융 자동 연동과 알림은 포함하지 않았습니다. 서버 미저장 상태는 별도로 표시합니다. 중요한 자료는 별도 백업도 보관해주세요.</p>')}</div>`}
const def=(name,label,type='text',extra={})=>({name,label,type,...extra});
const schema={
roles:{title:'역할·활동',hint:'본업, 사이드프로젝트, 가족과 나 자신까지. 역할마다 목적을 정해요.',fields:()=>[def('name','활동·역할 이름','text',{required:true,max:80}),def('kind','구분','select',{options:['본업','사이드프로젝트','알바','부업','개인사업','삶','기타']}),def('role','내 역할'),def('purpose','어떤 기여를 하고 싶은가요?','textarea'),def('hours','이번 주 계획 시간','number',{min:0,max:168,step:.5})]},
goals:{title:'목표·꿈·버킷리스트',hint:'중요한 이유부터 적어요. 구체적인 준비는 목표를 만든 뒤 추가할 수 있습니다.',fields:()=>[def('title','이루고 싶은 것','text',{required:true,max:120}),def('kind','유형','select',{options:['장기 목표','올해 목표','버킷리스트']}),def('role','연결할 역할','select',{options:roleOptions(),blank:'개인 목표'}),def('why','나에게 중요한 이유','textarea'),def('outcome','이루면 어떤 모습인가요?','textarea'),def('target','목표 시점','text',{placeholder:'예: 2028년 여름 / 내 속도로'}),def('obstacle','예상되는 나의 장애물','textarea',{placeholder:'예: 피곤하면 계획 전체를 미룬다'}),def('plan','장애물이 생겼을 때의 실행 계획','textarea',{placeholder:'만약 퇴근 후 피곤하면, 5분만 준비한다.'})]},
tasks:{title:'준비 단계·다음 행동',hint:'바로 시작할 수 있을 만큼 작고 구체적으로 적어요. 날짜는 선택입니다.',fields:()=>[def('title','무엇을 할까요?','text',{required:true,max:180}),def('goal','연결할 목표','select',{options:goalOptions(),blank:'없음'}),def('role','연결할 역할','select',{options:roleOptions(),blank:'미지정',help:'목표를 연결하면 해당 목표의 역할을 사용합니다.'}),def('date','실행·확인할 날짜','date'),def('workKind','업무·알바 구분','select',{options:['본업','사이드프로젝트','알바','개인·기타'],blank:'미지정'}),def('note','상세 메모 · 선택','textarea')],booleans:['done']},
notes:{title:'기록',hint:'일상·생각·업무 메모 모두 남길 수 있어요.',fields:()=>[def('text','남길 이야기','textarea',{required:true,max:6000}),def('date','날짜','date',{required:true,value:today,max:today}),def('role','연결할 역할','select',{options:roleOptions(),blank:'자유 기록'})]},
health:{title:'건강 체크인',hint:'날짜 외에 한 항목만 입력해도 됩니다. 같은 날짜는 기존 기록을 업데이트합니다.',fields:()=>[def('date','날짜','date',{required:true,value:today,max:today}),def('sleep','수면 시간','number',{min:0,max:24,step:.1,placeholder:'시간'}),def('weight','몸무게','number',{min:1,max:500,step:.1,placeholder:'kg'}),def('exercise','운동 여부','select',{options:['운동함','쉬었음'],blank:'미입력'}),def('minutes','활동·운동 시간 (분)','number',{min:0,max:1440,step:1,placeholder:'분 · 휴식은 0'}),def('mood','기분·컨디션','select',{options:['개운해요','괜찮아요','피곤해요','불안해요','무기력해요'],blank:'미입력'}),def('drink','음주','select',{options:['안 마심','마심'],blank:'미입력'}),def('memo','식단·활동 종류·몸의 변화','textarea')]},
people:{title:'중요한 사람',hint:'별칭으로 기록해도 괜찮아요.',fields:()=>[def('name','이름·별칭','text',{required:true,max:80}),def('group','관계','select',{options:['가족','친구','동료','기타']}),def('note','기억할 것·함께 하고 싶은 것','textarea')]},
moments:{title:'함께한 순간',hint:'시간은 선택입니다. 정확하게 재지 않아도 되고, 관계를 채점하지 않습니다.',needs:'people',fields:()=>[def('person','함께한 사람','select',{options:personOptions(),required:true,blank:'사람 선택'}),def('title','함께한 일','text',{required:true,max:120}),def('date','날짜','date',{required:true,value:today,max:today}),def('minutes','함께한 시간 (분)','number',{min:1,max:1440,step:1}),def('contactChannel','실제로 안부를 나눈 기록으로도 남기기','select',{options:[['','연락 기록에 포함하지 않기'],'전화','메시지','만남','기타']}),def('note','어떤 시간이었나요?','textarea')]},
issues:{title:'관계에서 챙길 일',hint:'필요한 대화나 공동 결정을 적고 다음 행동을 정해요. 날짜는 기록만 하며 자동 알림은 없습니다.',needs:'people',fields:()=>[def('person','관련된 사람','select',{options:personOptions(),required:true,blank:'사람 선택'}),def('title','챙길 일·이슈','text',{required:true,max:120}),def('next','다음 행동'),def('date','다시 확인할 날짜','date')],booleans:['done']},
investments:{title:'투자 현황',hint:'가격 자동 조회 없이 직접 입력한 스냅샷입니다. 금액 단위는 원입니다.',fields:()=>[def('name','투자명','text',{required:true,max:100}),def('principal','투자 원금 (원)','number',{required:true,min:0,step:1}),def('value','현재 평가액 (원)','number',{required:true,min:0,step:1}),def('date','평가 기준일','date',{required:true,value:today,max:today}),def('reason','투자한 이유·메모','textarea')]},
loans:{title:'대출 현황',hint:'금액 단위는 원입니다. 등록한 납부일은 자동으로 다음 달로 넘어가지 않습니다.',fields:()=>[def('name','대출명','text',{required:true,max:100}),def('balance','남은 원금 (원)','number',{required:true,min:0,step:1}),def('asof','잔액 기준일','date',{required:true,value:today,max:today}),def('rate','연 금리 (%)','number',{required:true,min:0,max:100,step:.01}),def('monthly','월 상환액 (원)','number',{required:true,min:0,step:1}),def('method','상환 방식','select',{options:['원리금균등','원금균등','만기일시','기타']}),def('date','다음 납부일','date'),def('maturity','만기','date')]},
incomes:{title:'추가 수입',hint:'알바·외주 등 받을 돈과 실제 입금 여부를 관리합니다.',fields:()=>[def('title','수입 내용','text',{required:true,max:120}),def('amount','금액 (원)','number',{required:true,min:0,step:1}),def('date','예정일·입금일','date',{required:true,value:today}),def('role','관련 활동','select',{options:roleOptions(),blank:'미지정'})],booleans:['done']},
decisions:{title:'결정과 피드백',hint:'드러커의 피드백 분석: 예상 결과를 적고 나중에 실제 결과와 비교합니다. 기본 점검은 9개월 후, 필요하면 조정하세요.',fields:()=>{const d=new Date(today+'T12:00:00+09:00');d.setUTCMonth(d.getUTCMonth()+9);return [def('title','중요한 결정·시도','text',{required:true,max:120}),def('created','결정일','date',{required:true,value:today,max:today}),def('expected','예상하는 결과','textarea',{required:true}),def('date','결과를 다시 확인할 날짜','date',{required:true,value:iso(d)}),def('actual','실제 결과 · 나중에 입력','textarea'),def('strength','여기서 드러난 강점·내가 성과를 내는 조건','textarea')]}},
timeLogs:{title:'실제로 쓴 시간',hint:'드러커의 시간 파악을 참고한 간단 기록입니다. 모든 시간을 채울 필요는 없습니다.',fields:()=>[def('title','무엇을 했나요?','text',{required:true,max:120}),def('role','역할','select',{options:roleOptions(),blank:'미지정'}),def('goal','연결할 목표','select',{options:db.goals.map(g=>[g.id,g.title]),blank:'연결 안 함'}),def('date','날짜','date',{required:true,value:today,max:today}),def('minutes','사용 시간 (분)','number',{required:true,min:1,max:1440,step:1}),def('workKind','기록 분류','select',{options:['본업','사이드프로젝트','알바','개인·기타'],blank:'미지정'}),def('employer','알바명·근무처 · 선택'),def('hourlyRate','알바 시급 (원) · 선택','number',{min:0,max:1000000000,step:1}),def('actualStartLocal','실제 시작 시각 · 선택','datetime-local'),def('actualEndLocal','실제 종료 시각 · 선택','datetime-local'),def('note','발견한 점','textarea')]}
};
function field(f,values={}){const fid='field-'+(++fieldCounter);const value=values[f.name]??f.value??'';const attrs=`name="${f.name}" id="${fid}" ${f.required?'required':''} ${f.min!==undefined?`min="${f.min}"`:''} ${f.max!==undefined&&f.type==='number'?`max="${f.max}"`:''} ${f.type==='date'&&f.max?`max="${f.max}"`:''} ${f.step?`step="${f.step}"`:''} ${f.type!=='number'&&f.type!=='date'?`maxlength="${typeof f.max==='number'?f.max:6000}"`:''} placeholder="${esc(f.placeholder||'')}"`;let control;if(f.type==='textarea')control=`<textarea ${attrs}>${esc(value)}</textarea>`;else if(f.type==='select'){const opts=f.options||[];control=`<select ${attrs}>${f.blank!==undefined?`<option value="">${esc(f.blank)}</option>`:''}${opts.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`}).join('')}</select>`}else control=`<input type="${f.type}" ${attrs} value="${esc(value)}">`;return `<label class="form-field" for="${fid}">${esc(f.label)}${f.required?' *':''}${control}${f.help?`<small>${esc(f.help)}</small>`:''}</label>`}
function modal(title,html){$('#modal').innerHTML=`<button class="close" type="button" data-action="close" aria-label="닫기">×</button><h2 id="dialog-title">${esc(title)}</h2>${html}`;if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){$('#modal').close()}
let editing=null;
function timeLogFields(schema,data){const actual=['actualStartLocal','actualEndLocal'],extra=['workKind','employer','hourlyRate'];return schema.fields().filter(f=>!actual.includes(f.name)&&!extra.includes(f.name)).map(f=>field(f,data)).join('')+'<details class="diary-extra" '+(data.actualStartLocal?'open':'')+'><summary>실제 시작·종료 · 상세 시간대 분석용</summary>'+schema.fields().filter(f=>actual.includes(f.name)).map(f=>field(f,data)).join('')+'<p class="muted">실제 시각을 알 때만 입력하세요. 예정 시각을 추정해서 채우지 않습니다. 시각을 비워도 실제 분 기록은 유지됩니다.</p></details><details class="diary-extra" '+(data.workKind==='알바'?'open':'')+'><summary>분류·알바 정보 · 선택</summary>'+schema.fields().filter(f=>extra.includes(f.name)).map(f=>field(f,data)).join('')+'<p class="muted">알바 분류의 시간과 시급으로만 예상 금액을 계산합니다. 실제 입금·세금·수당은 반영하지 않습니다.</p></details>';}
function editForm(table,key,values={}){if(table==='people'){relationPersonForm(key);return;}if(table==='incomes'){incomeForm(values,key);return;}const s=schema[table];if(!s)return;if(s.needs&&!db[s.needs].length){modal('먼저 사람을 추가해주세요',`<p class="intro">함께한 순간이나 이슈를 연결할 사람의 별칭을 먼저 등록해주세요.</p>${btn('사람 추가','edit',{table:'people'},'primary')}`);return}const existing=key?find(table,key):(table==='health'?db.health.find(h=>h.date===(values.date||today)):null);if(existing)key=existing.id;editing={table,key};const data={...values,...existing};if(table==='timeLogs'){data.actualStartLocal=window.HaruTimeStats.local(existing?.actualStart);data.actualEndLocal=window.HaruTimeStats.local(existing?.actualEnd);}modal(s.title,`<p class="intro">${s.hint}</p><form id="entityForm">${table==='timeLogs'?timeLogFields(s,data):s.fields().map(f=>field(f,data)).join('')}<p class="error" id="formError" role="alert"></p><div class="form-actions">${existing?btn('삭제','delete',{table,id:key},'delete'):''}${btn('취소','close')}<button class="primary">저장</button></div></form>`)}
function submitEntity(e){e.preventDefault();const {table,key}=editing,s=schema[table],data=Object.fromEntries(new FormData(e.target));for(const f of s.fields()){data[f.name]=(data[f.name]||'').trim();if(f.required&&!data[f.name]){$('#formError').textContent='필수 항목을 입력해주세요.';return}}
 if(table==='health'&&!Object.entries(data).some(([k,v])=>k!=='date'&&v!=='')){$('#formError').textContent='날짜 외에 한 항목 이상 입력해주세요.';return}
 if(table==='timeLogs'){try{Object.assign(data,window.HaruTimeStats.validateActual(data.actualStartLocal,data.actualEndLocal,data.minutes,data.date));delete data.actualStartLocal;delete data.actualEndLocal;}catch(error){$('#formError').textContent=error.message;return;}}
 if(table==='moments'){if(data.date>iso()){$('#formError').textContent='함께한 순간은 오늘까지 기록해주세요.';return}data.kind=data.contactChannel?'contact':'';}
 if(['tasks','timeLogs'].includes(table)&&data.goal)data.role=find('goals',data.goal)?.role||'';
 const sameDay=table==='health'?db.health.find(h=>h.date===data.date):null;
 if(sameDay&&key&&sameDay.id!==key){$('#formError').textContent='그 날짜에 기록이 이미 있어요. 해당 기록을 편집해주세요.';return}
 const original=key?find(table,key):sameDay;const item={...original,...data,id:original?.id||id()};for(const b of s.booleans||[])item[b]=original?.[b]||false;
 const ok=commit(n=>{const at=n[table].findIndex(x=>x.id===item.id);if(at<0)n[table].push(item);else n[table][at]=item;if(table==='goals')n.tasks.forEach(t=>{if(t.goal===item.id)t.role=item.role})});if(ok)closeModal();
}
function deleteEntity(table,key){const item=find(table,key);modal('기록을 삭제할까요?',`<p class="intro">${esc(item?.title||item?.name||item?.date||'선택한 기록')}<br>이 작업은 되돌릴 수 없습니다. 연결된 기록은 함께 삭제하지 않고 연결만 해제합니다.</p><div class="form-actions">${btn('취소','close')}${btn('삭제하기','delete-confirm',{table,id:key},'primary')}</div>`)}
function confirmDelete(table,key){if(!schema[table])return;const ok=commit(n=>{n[table]=n[table].filter(x=>x.id!==key);if(table==='roles'){for(const t of ['tasks','goals','notes','incomes','timeLogs'])n[t].forEach(x=>{if(x.role===key)x.role=''})}if(table==='goals')n.tasks.forEach(x=>{if(x.goal===key)x.goal=''});if(table==='people')for(const t of ['moments','issues'])n[t].forEach(x=>{if(x.person===key)x.person=''});if(table==='tasks')n.focus=n.focus.filter(f=>f.task!==key)},'삭제했어요.');if(ok)closeModal()}
function goalDetail(key){const g=find('goals',key);if(!g)return;modal(g.title,`<div class="goal-top">${tag(goalRole(g))}<span class="muted">${esc(g.target||'나의 속도로')}</span></div>${[['나에게 중요한 이유',g.why],['바라는 결과',g.outcome],['나를 막는 것',g.obstacle],['그 상황에서 할 작은 행동',g.plan]].map(([a,b])=>`<div class="source"><small>${a}</small><p>${esc(b||'아직 적지 않았어요.')}</p></div>`).join('')}<h3 style="margin:20px 0 10px">필요한 준비와 단계</h3><div>${lifeModel().allTasks.filter(t=>t.goal===key).map(linkedTaskRow).join('')||'<p class="empty">가장 먼저 할 작은 준비를 추가해보세요.</p>'}</div><div class="form-actions">${btn('목표 편집','edit',{table:'goals',id:key})}${btn('＋ 단계 추가','new-task',{goal:key,role:g.role},'primary')}</div>`)}
function focusForm(){const options=db.tasks.filter(t=>!t.done),cur=db.focus.find(f=>f.period===week);if(!options.length){modal('이번 주 한 걸음',`<p class="intro">중요하지만 급하지 않은 일 하나를 할 일로 추가한 뒤 선택해보세요.</p>${btn('할 일 추가','edit',{table:'tasks'},'primary')}`);return}modal('이번 주 한 걸음 고르기',`<p class="intro">중요한 역할이나 장기 목표를 앞으로 움직일 행동 하나를 정해요.</p><form id="focusForm">${field(def('task','집중할 행동','select',{options:options.map(t=>[t.id,t.title])}),{task:cur?.task})}<div class="form-actions"><button class="primary">이번 주 행동으로 지정</button></div></form>`)}
function visionForm(){modal('나의 방향·원칙·강점',`<p class="intro">코비의 방향 설정과 드러커의 강점 파악을 참고한 나만의 메모입니다.</p><form id="visionForm">${field(def('vision','5년 뒤 어떤 하루를 살고 싶은가요?','textarea'),db.profile)}${field(def('principle','선택할 때 돌아올 원칙 한 줄','textarea'),db.profile)}${field(def('strengths','실제 경험에서 발견한 강점과 성과를 내는 조건','textarea'),db.profile)}<div class="form-actions"><button class="primary">방향 저장</button></div></form>`)}
function capture(){const choices=[['incomes','추가 알바 수입','총액·수행월·실제 입금 확인'],['notes','생각·일상 기록','한 줄부터'],['tasks','할 일·다음 행동','목표를 작은 단계로'],['health','건강 체크인','한 항목이면 충분'],['moments','함께한 순간','사람과 시간'],['issues','챙길 관계 이슈','필요한 대화'],['goals','목표·버킷리스트','원하는 삶의 모습'],['decisions','중요한 결정','예상과 실제 결과'],['timeLogs','실제 사용 시간','내 시간을 알아가기']];modal('무엇을 남길까요?',`<p class="intro">지금 필요한 기록만 골라주세요.</p><div class="picker">${btn('오늘 하루 일기','daily-open',{},'outline')}${choices.map(([table,a,b])=>`<button data-action="edit" data-table="${table}">${a}<small>${b}</small></button>`).join('')}</div>`)}
function backup(){modal('기록 백업·복원',`<p class="intro">서버 기록도 파일로 별도 백업할 수 있습니다. 이 기기에 서버 미저장 변경이 있다면 함께 내려받습니다. 파일에는 모든 입력 내용이 포함되므로 안전한 곳에 보관하세요.</p><div class="backupbox"><b>전체 기록 내려받기</b><p>JSON 형식 · 투자·건강·관계 등 입력 내용 포함</p><div style="margin-top:15px">${btn('백업 파일 다운로드','download',{},'primary')}</div></div><form id="restoreForm"><div class="backupbox"><label for="restoreFile"><b>하루 백업 파일 복원</b></label><p>현재 형식의 백업만 지원합니다. 다음 단계에서 내용을 확인한 뒤 현재 데이터를 교체합니다.</p><input id="restoreFile" name="file" type="file" accept="application/json,.json" required></div><div class="form-actions"><button class="outline">파일 확인</button></div><p class="error" id="restoreError" role="alert"></p></form>`)}
function download(){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='haru-backup-'+today+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('백업 파일을 다운로드합니다.')}
let pendingRestore=null;
async function checkRestore(e){e.preventDefault();try{const file=e.target.file.files[0];if(file.size>10*1024*1024)throw Error('파일은 10MB 이하만 가능합니다.');const data=JSON.parse(await file.text());if(!validState(data))throw Error('현재 하루 백업 형식과 맞지 않습니다.');pendingRestore=data;modal('백업으로 교체할까요?',`<p class="intro">목표 ${data.goals.length}개 · 기록 ${data.notes.length}개 · 건강 ${data.health.length}일 · 관계 ${data.people.length}명<br>현재 계정의 기록 전체를 이 파일로 교체하고 서버에 저장합니다. 필요하면 먼저 현재 데이터를 백업하세요.</p><div class="form-actions">${btn('취소','close')}${btn('현재 데이터 백업','download',{},'outline')}${btn('확인 후 복원','restore-confirm',{},'primary')}</div>`)}catch(error){$('#restoreError').textContent=error.message||'파일을 읽을 수 없습니다.'}}
function render(){if(!DEMO&&window.HaruSync&&HaruSync.gate()){$('#nav').innerHTML='';$('#breadcrumb').textContent='나의 공간 / 로그인';$('#app').innerHTML=HaruSync.gateHTML();return;}if(!navigation.some(n=>n[0]===page)&&page!=='guide')page='home';$('#nav').innerHTML=navigation.map(([p,i,t,c])=>`<button data-action="go" data-page="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}><span class="nav-icon">${i}</span>${t}<span class="cadence">${c}</span></button>`).join('');$('#breadcrumb').textContent='나의 공간 / '+(navigation.find(n=>n[0]===page)?.[2]||'설계 근거');const views={home,calendar:calendarPage,notes:notesPage,goals:goalsPage,work:workPage,money:moneyPage,health:healthPage,relations:relationsPage,review:reviewPage,guide:guidePage};$('#app').innerHTML=(DEMO?'<div class="notice" style="margin-top:18px">예시 데이터로 둘러보는 화면입니다. 입력과 변경은 실제 기록과 분리된 데모 공간에 저장됩니다. <a href="./">내 기록 화면으로 돌아가기</a></div>':'')+(storageError?'<div class="notice">기존 저장 데이터를 읽지 못해 편집을 중지했습니다. 기존 데이터를 덮어쓰지 않습니다. 백업 파일이 있다면 백업 메뉴에서 복원하세요.</div>':'')+views[page]();document.title='하루 · '+(navigation.find(n=>n[0]===page)?.[2]||'설계 근거');window.HaruCalendar?.mount();refreshTimeAnalytics();}
function go(p){closeModal();page=p;filter='전체';location.hash=p;render();scrollTo(0,0)}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const d=el.dataset;if(!DEMO&&window.HaruSync&&HaruSync.gate()&&d.action!=='close')return;switch(d.action){case 'go':go(d.page);break;case 'guide':go('guide');break;case 'close':closeModal();break;case 'capture':capture();break;case 'edit':editForm(d.table,d.id);break;case 'review-google-task':window.HaruCalendar?.reviewTask(d.key);break;case 'new-goal':editForm('goals',null,{role:d.role});break;case 'open-time':calendarTab='time';go('calendar');break;case 'calendar-tab':calendarTab=d.tab;render();break;case 'time-range':timeMonthDraft=null;window.HaruCalendar?.setRange(d.range);refreshTimeAnalytics();break;case 'time-day':selectedTimeDay=d.day;refreshTimeAnalytics();break;case 'money-goal-new':moneyGoalForm(null,d.kind);break;case 'money-goal-edit':moneyGoalForm(d.id);break;case 'money-goal-update':moneyGoalUpdate(d.id);break;case 'money-goal-check':if(updateMoneyPlan(plan=>{const g=plan.goals.find(g=>g.id===d.id);if(g)moneyCheckpoint(g,db)}))closeModal();break;case 'money-goal-delete':modal('자금 목표를 삭제할까요?',`<p class="intro">목표의 점검 이력도 삭제됩니다. 원본 투자·대출 기록은 유지됩니다.</p><div class="form-actions">${btn('취소','close')}${btn('목표 삭제하기','money-goal-delete-confirm',{id:d.id},'delete')}</div>`);break;case 'money-goal-delete-confirm':if(updateMoneyPlan(plan=>{plan.goals=plan.goals.filter(g=>g.id!==d.id)}))closeModal();break;case 'income-new':incomeForm();break;case 'income-edit':incomeForm({},d.id);break;case 'income-from-time':incomeFromTime(d.id);break;case 'income-month':incomeMonth=d.month;render();break;case 'new-parttime':editForm('timeLogs',null,{workKind:'알바'});break;case 'new-task':editForm('tasks',null,{role:d.role||'',goal:d.goal||''});break;case 'relation-pick':relationActionForm('pick',d.id);break;case 'relation-contact':relationActionForm('contact',d.id);break;case 'relation-snooze':relationActionForm('snooze',d.id);break;case 'relation-anniversary':relationActionForm('anniversary',d.id);break;case 'relation-dismiss':commit(n=>{const p=n.people.find(p=>p.id===d.id);if(p)p.reachOutStatus='dismissed'});break;case 'relation-ann-delete':commit(n=>{const p=n.people.find(p=>p.id===d.id);if(p)p.anniversaries=JSON.stringify(HaruRelationships.anniversaries(p).filter(a=>a.id!==d.event))});break;case 'new-moment':editForm('moments',null,{person:d.person});break;case 'goal':goalDetail(d.id);break;case 'vision':visionForm();break;case 'focus':focusForm();break;case 'filter':filter=d.value;render();break;case 'delete':deleteEntity(d.table,d.id);break;case 'delete-confirm':confirmDelete(d.table,d.id);break;case 'review-kind':reviewKind=d.kind;reviewPeriod=d.kind==='일간'?today:d.kind==='주간'?week:d.kind==='분기'?quarter:today.slice(0,4);render();break;case 'health-date':{const h=db.health.find(h=>h.date===d.date);editForm('health',h?.id,{date:d.date});break}case 'home-weekly':reviewKind='주간';reviewPeriod=week;go('review');break;case 'daily-open':reviewKind='일간';reviewPeriod=d.date||today;go('review');break;case 'review-open':{const r=find('reviews',d.id);if(!r)break;reviewKind=r.kind;reviewPeriod=r.period;go('review');break}case 'review-task':{const r=find('reviews',d.id);if(!r||!reviewNext(r).trim())break;if(db.tasks.some(t=>t.review===r.id)){toast('이미 할 일에 가져온 행동입니다.');break}commit(n=>n.tasks.push({id:id(),title:reviewNext(r).trim(),goal:'',role:'',date:'',done:false,review:r.id}),'지난 행동을 할 일로 가져왔어요.');break}case 'backup':backup();break;case 'download':download();break;case 'restore-confirm':if(pendingRestore&&!DEMO&&window.HaruSync){if(commit(n=>{for(const k of Object.keys(n))delete n[k];Object.assign(n,pendingRestore)})){pendingRestore=null;closeModal()}break;}if(pendingRestore){try{localStorage.setItem(KEY,JSON.stringify(pendingRestore));db=pendingRestore;pendingRestore=null;storageError=false;closeModal();render();toast('백업에서 복원했어요.')}catch{toast('복원하지 못했어요. 브라우저 저장 공간을 확인해주세요.')}}break;}});
document.addEventListener('change',e=>{const t=e.target;if(!t.dataset.toggle)return;const table=t.dataset.toggle;if(!['tasks','issues','incomes'].includes(table))return;const key=t.dataset.id,checked=t.checked;const goalId=table==='tasks'?find('tasks',key)?.goal:null;commit(n=>{const item=n[table].find(x=>x.id===key);if(item)item.done=checked},checked?'완료로 표시했어요.':'다시 진행 중으로 표시했어요.');if($('#modal').open&&goalId&&$('#modal').querySelector('[data-action="new-task"]'))goalDetail(goalId)});
document.addEventListener('input',e=>{if(e.target.id==='searchNotes'){const q=e.target.value.toLocaleLowerCase();$('#noteResults').innerHTML=noteList(db.notes.filter(n=>(n.text+' '+byName('roles',n.role,'')).toLocaleLowerCase().includes(q)))}});
document.addEventListener('submit',e=>{if(e.target.id==='time-month-form'){e.preventDefault();const requested=e.target.month.value;timeMonthDraft=null;window.HaruCalendar?.setMonth(requested);refreshTimeAnalytics();return;}if(e.target.id==='income-record-form'){submitIncome(e);return;}if(e.target.id==='income-month-form'){e.preventDefault();const month=e.target.month.value;if(/^\d{4}-\d{2}$/.test(month)){incomeMonth=month;render();}return;}if(e.target.id==='entityForm'){submitEntity(e);return}if(e.target.id==='restoreForm'){checkRestore(e);return}e.preventDefault();if(e.target.id==='weekNote'){const value=e.target.next.value.trim();commit(n=>{let r=n.reviews.find(r=>r.kind==='주간'&&r.period===week);if(!r){r={id:id(),kind:'주간',period:week,result:'',obstacle:'',next:'',stop:''};n.reviews.push(r)}r.next=value;r.savedAt=new Date().toISOString()})}if(e.target.id==='reviewForm'){const fields=Object.fromEntries(new FormData(e.target));if(reviewKind==='일간'&&!fields.result?.trim()){$('#dailyError').textContent='오늘의 이야기를 한 줄 남겨주세요.';return}commit(n=>{let r=n.reviews.find(r=>r.kind===reviewKind&&r.period===reviewPeriod);if(!r){r={id:id(),kind:reviewKind,period:reviewPeriod,result:'',obstacle:'',next:'',stop:''};n.reviews.push(r)}Object.assign(r,fields);r.savedAt=new Date().toISOString()})}if(e.target.id==='dailyDateForm'){const day=e.target.day.value;if(day&&day<=today){reviewKind='일간';reviewPeriod=day;render()}}if(e.target.id==='focusForm'){const task=e.target.task.value;if(commit(n=>{n.focus=n.focus.filter(f=>f.period!==week);n.focus.push({id:id(),period:week,task})}))closeModal()}if(e.target.id==='visionForm'){const profile=Object.fromEntries(new FormData(e.target));if(commit(n=>n.profile=profile))closeModal()}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'home';if(next!==page){page=next;filter='전체';render();scrollTo(0,0)}});
if(!DEMO&&window.HaruSync){void HaruSync.start({getState:()=>db,setState:state=>{db=state;storageError=false;render();},validate:validState,defaults,render,toast,legacyKey:KEY});}else render();

function demoState(){const d=defaults();d.profile={vision:'일에 의미를 느끼고, 가족과 시간을 나누며, 가고 싶은 곳을 걸어서 여행할 수 있는 삶.',principle:'더 많은 일을 하기보다, 나에게 중요한 것에 먼저 시간을 쓴다.',strengths:'복잡한 문제를 정리하고, 다음 의사결정으로 연결할 때 집중이 잘 된다. 실제 경험을 더 모아 확인하기.'};d.roles[0].purpose='투자 판단의 질을 높이고 회사의 장기 성과에 기여하기';d.roles[0].hours='35';d.roles[1].purpose='사용자 문제를 확인하고 작은 실험을 끝내기';d.roles[1].hours='5';d.roles[2].purpose='다음 버전의 우선순위를 분명히 하기';d.roles[2].hours='3';d.goals=[{id:'demo-goal1',title:'워크스워크 첫 사용자 인터뷰',kind:'올해 목표',role:'works',why:'실제로 필요한 것을 만들고 싶다.',outcome:'사용자 세 명의 문제를 이해하고 다음 실험을 정한다.',target:'올해 안에',obstacle:'기능을 더 만들다가 인터뷰를 미룬다.',plan:'수요일 저녁이 되면 질문 세 개를 먼저 작성한다.'},{id:'demo-goal2',title:'아이슬란드에서 오로라 보기',kind:'버킷리스트',role:'self',why:'오래 기억할 새로운 경험을 만들기.',outcome:'시간과 예산을 마련하고 여행을 떠난다.',target:'2028년 겨울',obstacle:'비용이 막연해서 계속 미룬다.',plan:'일요일 저녁 식사 후, 예산을 10분만 정리한다.'},{id:'demo-goal3',title:'가족과 여유로운 저녁 보내기',kind:'장기 목표',role:'family',why:'함께 있어도 일만 생각하는 시간을 줄이고 싶다.',outcome:'편안하게 이야기하는 저녁을 꾸준히 만든다.',target:'나의 속도로',obstacle:'급한 업무 연락에 계속 반응한다.',plan:'식사를 시작하면 휴대폰을 다른 곳에 둔다.'},{id:'demo-goal4',title:'핵심 투자 검토 기준 정리',kind:'올해 목표',role:'invest',why:'판단 과정을 일관되게 만들기.',outcome:'회의에서 활용할 검토 항목을 정리한다.',target:'이번 분기',obstacle:'자료를 모으는 데 시간을 다 쓴다.',plan:'초안을 먼저 한 페이지로 작성한다.'},{id:'demo-goal5',title:'PWR 다음 버전 방향 정하기',kind:'올해 목표',role:'pwr',why:'핵심 가치에 집중하기.',outcome:'이번 버전에서 할 일과 하지 않을 일을 정한다.',target:'이번 분기',obstacle:'동시에 너무 많이 시도한다.',plan:'기능 후보 중 가장 중요한 하나만 고른다.'}];d.tasks=[{id:'dt1',title:'인터뷰 질문 세 개 작성하기',goal:'demo-goal1',role:'works',date:addDays(today,2),done:false},{id:'dt2',title:'사용자 후보 세 명 정하기',goal:'demo-goal1',role:'works',date:'',done:true},{id:'dt3',title:'항공·숙소 예상 비용 알아보기',goal:'demo-goal2',role:'self',date:'',done:false},{id:'dt4',title:'함께 저녁 먹을 날짜 정하기',goal:'demo-goal3',role:'family',date:addDays(today,3),done:false},{id:'dt5',title:'투자 검토 기준 초안 한 페이지',goal:'demo-goal4',role:'invest',date:addDays(today,1),done:false},{id:'dt6',title:'이번 버전에서 하지 않을 일 정하기',goal:'demo-goal5',role:'pwr',date:'',done:false}];d.focus=[{id:'df',period:week,task:'dt1'}];d.notes=[{id:'dn1',date:today,role:'self',text:'이번 주에는 새로운 일을 더 벌이기보다, 시작한 일 하나를 끝내보자.'}];d.health=[{id:'dh1',date:today,exercise:'운동함',sleep:'7',weight:'72',minutes:'30',mood:'괜찮아요',drink:'안 마심',memo:'예시 기록 · 저녁 산책'}];d.people=[{id:'dp1',name:'가족',group:'가족',note:'함께하는 시간에는 이야기에 집중하기.'}];d.moments=[{id:'dm1',person:'dp1',title:'함께 저녁 먹고 산책',date:today,minutes:'90',note:'휴대폰 없이 이야기한 시간.'}];d.issues=[{id:'di1',person:'dp1',title:'가족 여행 날짜 이야기하기',next:'가능한 주말을 물어보기',date:addDays(today,6),done:false}];d.investments=[{id:'dinv',name:'분산 투자 · 예시',principal:'45000000',value:'48500000',date:today,reason:'장기 목표를 위한 분산 투자'}];d.loans=[{id:'dl',name:'주택 관련 대출 · 예시',balance:'70000000',asof:today,rate:'4.2',monthly:'580000',method:'원리금균등',date:addDays(today,14),maturity:'2040-10-15'}];d.incomes=[{id:'dinc',title:'외주 프로젝트 · 예시',amount:'450000',date:addDays(today,9),role:'works',done:false}];d.decisions=[{id:'dd',title:'사이드프로젝트에 집중 시간 배정',created:today,expected:'작은 실험을 끝내고 다음 방향을 판단할 근거를 얻는다.',date:addDays(today,90),actual:'',strength:''}];d.reviews=[{id:'demo-review-prev',kind:'주간',period:addDays(week,-7),result:'워크스워크의 인터뷰 후보를 정리했다.',obstacle:'회의 후 작은 시간만 남아 중요한 일을 미뤘다.',next:'인터뷰 질문 세 개를 작성하고, 집중할 시간을 먼저 확보하기.',stop:'이번 주 새 기능 추가는 미루기.',savedAt:new Date(today+'T09:00:00+09:00').toISOString()}];d.reviews.push({id:'demo-diary',kind:'일간',period:today,learning:'작은 산책과 대화만으로도 하루의 느낌이 달라졌다. 중요한 시간은 남기를 기다리기보다 먼저 확보해야겠다.',experiment:'퇴근 후 휴대폰을 내려두면, 가족과 10분 먼저 이야기한다.',result:'오늘은 바쁜 하루 중에도 잠깐 산책을 했다. 가족과 저녁을 먹으며 나눈 이야기가 오래 남는다. 모든 일을 끝내지는 못했지만, 나에게 중요한 시간을 조금은 지켰다.',obstacle:'오후에는 조금 피곤했지만 산책 후 마음이 가벼워졌다.',next:'다 끝내려고 하기보다 중요한 일 하나부터 시작하자.',stop:'별일 아닌 이야기를 편하게 나눌 수 있었던 저녁.',savedAt:new Date().toISOString()});d.timeLogs=[{id:'demo-time-1',title:'투자 검토 자료 정리',role:'invest',date:today,minutes:'90',note:'집중한 구간만 기록한 예시'},{id:'demo-time-2',title:'인터뷰 질문 초안',role:'works',date:today,minutes:'45',note:''},{id:'demo-time-3',title:'산책과 생각 정리',role:'self',date:today,minutes:'30',note:''}];return d;}

window.HaruCalendar?.start({
 ready:()=>DEMO||!!window.HaruSync?.isLoaded(),
 account:()=>DEMO?'demo':window.HaruSync?.getUserId()||null,
 preferences:()=>{try{const data=JSON.parse(db.profile.googleCalendar||'{}');return data&&typeof data==='object'?data:{}}catch{return {}}},
 savePreferences:settings=>commit(n=>{n.profile.googleCalendar=JSON.stringify(settings)}),
 roles:()=>db.roles,
 goals:()=>db.goals,
 onSnapshotChanged:()=>{refreshTimeAnalytics();refreshLifeOverview();},
 importedIncome:key=>db.incomes.find(r=>r.googleIncomeKey===key),
 reviewIncome:values=>incomeForm(values),
 importedMemo:key=>db.notes.find(n=>n.googleMemoKey===key),
 openMemo:key=>editForm('notes',key),
 recordMemo:record=>{if(db.notes.some(n=>n.googleMemoKey===record.googleMemoKey)){toast('이미 가져온 메모입니다.');return false;}return commit(n=>n.notes.push({...record,id:id()}));},
 importedTask:key=>db.tasks.find(t=>t.googleTaskKey===key),
 recordTask:record=>commit(n=>{const old=n.tasks.find(t=>t.googleTaskKey===record.googleTaskKey);if(old)Object.assign(old,record);else n.tasks.push({goal:'',...record,id:id()});}),
 imported:key=>db.timeLogs.find(l=>l.googleEventKey===key),
 openLog:key=>editForm('timeLogs',key),
 recordEvent:record=>{if(db.timeLogs.some(l=>l.googleEventKey===record.googleEventKey)){toast('이미 확인한 일정입니다. 기존 시간 기록을 수정해주세요.');return false;}return commit(n=>{n.timeLogs.push({...record,id:id()})});},
 toast
});

document.addEventListener('input',e=>{if(e.target.id==='time-month')timeMonthDraft=e.target.value;});
